window.SCENARIOS_V8 = [{"title":"導入 ─ 古き家と古き呪","folder":"chapter_00_intro","taps":[{"no":1,"img":"assets/images/chapter_00_intro/IMG-001.webp","pages":["北山の懐ふかく、\n白壁の屋敷がひっそりと佇んでいた。"],"text":"北山の懐ふかく、\n白壁の屋敷がひっそりと佇んでいた。","pages_en":["Deep in the folds of Kitayama\nstood a white-walled manor,\nquiet and hidden from the world."],"text_en":"Deep in the folds of Kitayama\nstood a white-walled manor,\nquiet and hidden from the world."},{"no":2,"img":"assets/images/chapter_00_intro/IMG-002.webp","pages":["屋敷の北の奥には、\n籠目模様の格子戸を持つ、\n座牢の一室があった。"],"text":"屋敷の北の奥には、\n籠目模様の格子戸を持つ、\n座牢の一室があった。","pages_en":["In the northernmost recess of the manor\nlay a small room, the Cell,\nsealed by a latticed door\nof interlocking kagome patterns."],"text_en":"In the northernmost recess of the manor\nlay a small room, the Cell,\nsealed by a latticed door\nof interlocking kagome patterns."},{"no":3,"img":"assets/images/chapter_00_intro/IMG-003.webp","pages":["古より、この地にはひとつの所作が、\nひっそりと語り継がれてきた。\n霊柩に遭うた折には、\n両の親指を拳の中に隠すのだという。","さすれば、親が連れ去られずに\n済むのだと。古き家には、古き呪が、\nいまもひそやかに息づいていた。"],"text":"古より、この地にはひとつの所作が、\nひっそりと語り継がれてきた。\n霊柩に遭うた折には、\n両の親指を拳の中に隠すのだという。\nさすれば、親が連れ去られずに\n済むのだと。古き家には、古き呪が、\nいまもひそやかに息づいていた。","pages_en":["From ancient days, in this land\na single custom was quietly passed down.\nWhen one meets a funeral bier,\none must hide both thumbs within one's fists.","So the elders said,\nlest a parent be taken away.\nIn this old house, an old curse\nstill breathed, softly and unseen."],"text_en":"From ancient days, in this land\na single custom was quietly passed down.\nWhen one meets a funeral bier,\none must hide both thumbs within one's fists.\nSo the elders said,\nlest a parent be taken away.\nIn this old house, an old curse\nstill breathed, softly and unseen."},{"no":4,"img":"assets/images/chapter_00_intro/IMG-004.webp","pages":["その家には、近隣の者さえ滅多に\n目にすることの叶わぬ、ひとりの娘がいた。\n噂に聞こえる限りでは、娘の容姿はことの\nほか優れ、肌は初雪のごとく白いという。","これは、外の世界に恋い焦がれる\nひとりの娘の物語である。"],"text":"その家には、近隣の者さえ滅多に\n目にすることの叶わぬ、ひとりの娘がいた。\n噂に聞こえる限りでは、娘の容姿はことの\nほか優れ、肌は初雪のごとく白いという。\nこれは、外の世界に恋い焦がれる\nひとりの娘の物語である。","pages_en":["Within this manor lived a girl,\nseldom seen even by those close by.\nRumor held her beauty exceptional,\nher skin white as the first snowfall.","This is the tale of a girl\nwho longed for the world outside."],"text_en":"Within this manor lived a girl,\nseldom seen even by those close by.\nRumor held her beauty exceptional,\nher skin white as the first snowfall.\nThis is the tale of a girl\nwho longed for the world outside."}]},{"title":"第一章 ─ 月の昏き夜の踏み出し","folder":"chapter_00_intro","taps":[{"no":1,"img":"assets/images/chapter_00_intro/IMG-005.webp","pages":["月の昏き夜であった。\n北山の懐に抱かれた屋敷は、\n白壁の輪郭だけを淡く闇に滲ませ、\nひっそりと沈んでいる。"],"text":"月の昏き夜であった。\n北山の懐に抱かれた屋敷は、\n白壁の輪郭だけを淡く闇に滲ませ、\nひっそりと沈んでいる。","pages_en":["It was a moonless night.\nThe manor cradled by Kitayama\ntraced only the pale outline of its walls\nagainst the darkness."],"text_en":"It was a moonless night.\nThe manor cradled by Kitayama\ntraced only the pale outline of its walls\nagainst the darkness."},{"no":2,"img":"assets/images/chapter_00_intro/IMG-006.webp","pages":["母屋の灯はとうに落とされていた。\n書斎の襖の隙よりも、\n奥座敷の障子の縁よりも、\nもはやひとすじの光も漏れてはいない。"],"text":"母屋の灯はとうに落とされていた。\n書斎の襖の隙よりも、\n奥座敷の障子の縁よりも、\nもはやひとすじの光も漏れてはいない。","pages_en":["The lights of the main house were long out.\nNo thread of light leaked\nfrom the study or the inner parlor,\nnot even a single seam."],"text_en":"The lights of the main house were long out.\nNo thread of light leaked\nfrom the study or the inner parlor,\nnot even a single seam."},{"no":3,"img":"assets/images/chapter_00_intro/IMG-007.webp","pages":["家長の祖父は、寝所の脇息に頬を預けて、\n深い眠りに落ちている。\n床の脇には、火の落ちた火桶が、\nわずかに灰の白さを留めていた。"],"text":"家長の祖父は、寝所の脇息に頬を預けて、\n深い眠りに落ちている。\n床の脇には、火の落ちた火桶が、\nわずかに灰の白さを留めていた。","pages_en":["The elder grandfather leaned against\nan armrest by his bed, deep in sleep.\nBeside him, a brazier now cold\nheld only the pallor of ash."],"text_en":"The elder grandfather leaned against\nan armrest by his bed, deep in sleep.\nBeside him, a brazier now cold\nheld only the pallor of ash."},{"no":4,"img":"assets/images/chapter_00_intro/IMG-008.webp","pages":["父の寝間では、酒の残り香が\n枕元の屛風の絹に染み込み、\n父はその匂いに包まれて鼾を立てている。","母はその傍らで、目だけを開き、\n襖の格子に映る月の影を、\n長く見つめている。"],"text":"父の寝間では、酒の残り香が\n枕元の屛風の絹に染み込み、\n父はその匂いに包まれて鼾を立てている。\n母はその傍らで、目だけを開き、\n襖の格子に映る月の影を、\n長く見つめている。","pages_en":["In the father's bedchamber,\nthe scent of stale sake had seeped\ninto the silk of the folding screen,\nand there he snored, wrapped in it.","The mother lay at his side,\nher eyes only open,\nlong watching the moonlit shadow\ncast on the lattice of the sliding door."],"text_en":"In the father's bedchamber,\nthe scent of stale sake had seeped\ninto the silk of the folding screen,\nand there he snored, wrapped in it.\nThe mother lay at his side,\nher eyes only open,\nlong watching the moonlit shadow\ncast on the lattice of the sliding door."},{"no":5,"img":"assets/images/chapter_00_intro/IMG-009.webp","pages":["屋敷の北の隅、北面の座牢では、\nひとりの娘が、静かに身を起こした。\n月の光が、座牢の高窓の格子をくぐり、\n畳の上に細い縞を落としている。","娘の頬と肩がその縞に切られ、\n白く浮かび上がる。\n十六の輪郭であった。"],"text":"屋敷の北の隅、北面の座牢では、\nひとりの娘が、静かに身を起こした。\n月の光が、座牢の高窓の格子をくぐり、\n畳の上に細い縞を落としている。\n娘の頬と肩がその縞に切られ、\n白く浮かび上がる。\n十六の輪郭であった。","pages_en":["In the northern corner of the manor,\nin the Cell of the north wall,\na girl quietly raised herself up.\nMoonlight through the high window's lattice","cast thin stripes across the tatami.\nHer cheek and shoulder,\ncut by those stripes,\nrose pale in the light.","She was sixteen years old."],"text_en":"In the northern corner of the manor,\nin the Cell of the north wall,\na girl quietly raised herself up.\nMoonlight through the high window's lattice\ncast thin stripes across the tatami.\nHer cheek and shoulder,\ncut by those stripes,\nrose pale in the light.\nShe was sixteen years old."},{"no":6,"img":"assets/images/chapter_00_intro/IMG-010.webp","pages":["娘は紫紺の羽織を肩に重ね、\n膝で格子戸の前まで進む。その指は、\nこれまで一度も触れたことのない錠の\n冷たさに、一瞬すくんでから、","ゆっくりとその金具にかけられた。\n錠は古い造作のものであった。\n日々の差配を任された老番頭が、\n夕暮れに必ず確かめてゆく錠である。","けれども今宵にかぎって、その金具は、\n娘の手の中で、ゆるりと外れた。"],"text":"娘は紫紺の羽織を肩に重ね、\n膝で格子戸の前まで進む。その指は、\nこれまで一度も触れたことのない錠の\n冷たさに、一瞬すくんでから、\nゆっくりとその金具にかけられた。\n錠は古い造作のものであった。\n日々の差配を任された老番頭が、\n夕暮れに必ず確かめてゆく錠である。\nけれども今宵にかぎって、その金具は、\n娘の手の中で、ゆるりと外れた。","pages_en":["The girl drew a deep-violet haori\nover her shoulders,\nand crept on her knees to the lattice.\nHer fingers, never before touching a lock,","hesitated an instant at its cold,\nthen slowly closed around the fitting.\nIt was an old lock,\nchecked each dusk by the old head clerk.","Yet on this night, and this night alone,\nthe fitting yielded softly\nwithin the girl's hand."],"text_en":"The girl drew a deep-violet haori\nover her shoulders,\nand crept on her knees to the lattice.\nHer fingers, never before touching a lock,\nhesitated an instant at its cold,\nthen slowly closed around the fitting.\nIt was an old lock,\nchecked each dusk by the old head clerk.\nYet on this night, and this night alone,\nthe fitting yielded softly\nwithin the girl's hand."},{"no":7,"img":"assets/images/chapter_00_intro/IMG-011.webp","pages":["廊下には誰もいない。\n書斎の床の杉板も、奥座敷の畳も、\nことりとも音を立てぬ。","屋敷のすべてが、\n息を潜めているかのようであった。\n娘は戸の隙より、紫紺の羽織の裾を引いて、\n闇の中へ滑り出た。"],"text":"廊下には誰もいない。\n書斎の床の杉板も、奥座敷の畳も、\nことりとも音を立てぬ。\n屋敷のすべてが、\n息を潜めているかのようであった。\n娘は戸の隙より、紫紺の羽織の裾を引いて、\n闇の中へ滑り出た。","pages_en":["No one was in the hall.\nNeither the cedar boards of the study\nnor the tatami of the inner parlor\nmade the faintest sound.","The whole manor seemed\nto be holding its breath.\nThe girl slipped through the crack,\nthe hem of her haori trailing into darkness."],"text_en":"No one was in the hall.\nNeither the cedar boards of the study\nnor the tatami of the inner parlor\nmade the faintest sound.\nThe whole manor seemed\nto be holding its breath.\nThe girl slipped through the crack,\nthe hem of her haori trailing into darkness."},{"no":8,"img":"assets/images/chapter_00_intro/IMG-012.webp","pages":["屋敷の外では、\n夜霧が庭の植え込みの足元から、\nゆっくりと立ち昇り始めるところであった。"],"text":"屋敷の外では、\n夜霧が庭の植え込みの足元から、\nゆっくりと立ち昇り始めるところであった。","pages_en":["Outside the manor,\nnight mist had begun to rise\nfrom the feet of the garden shrubs,\nslow and pale."],"text_en":"Outside the manor,\nnight mist had begun to rise\nfrom the feet of the garden shrubs,\nslow and pale."}]},{"title":"第二章 ─ 座牢の朝","folder":"chapter_01","taps":[{"no":1,"img":"assets/images/chapter_01/IMG-013.webp","pages":["夜が明けてゆく。\n山々の闇は峰の際からしだいに薄れ、\n白壁の屋敷が、藍の底から\n静かに浮かび上がってきた。"],"text":"夜が明けてゆく。\n山々の闇は峰の際からしだいに薄れ、\n白壁の屋敷が、藍の底から\n静かに浮かび上がってきた。","pages_en":["Dawn was breaking.\nThe darkness of the mountains thinned\nfrom the ridges outward,\nand the white-walled manor rose","quietly from the indigo depths."],"text_en":"Dawn was breaking.\nThe darkness of the mountains thinned\nfrom the ridges outward,\nand the white-walled manor rose\nquietly from the indigo depths."},{"no":2,"img":"assets/images/chapter_01/IMG-014.webp","pages":["北山の屋敷の朝は静かである。\n塀の向こうの集落から、\n雀の声が遠く伝わってくる。","陽が、東の山の稜線を\nひとつ越えたところであった。"],"text":"北山の屋敷の朝は静かである。\n塀の向こうの集落から、\n雀の声が遠く伝わってくる。\n陽が、東の山の稜線を\nひとつ越えたところであった。","pages_en":["The mornings of the Kitayama manor\nwere quiet.\nFrom the village beyond the wall,\nthe voices of sparrows drifted faintly.","The sun had just crested\nthe ridge of the eastern hills."],"text_en":"The mornings of the Kitayama manor\nwere quiet.\nFrom the village beyond the wall,\nthe voices of sparrows drifted faintly.\nThe sun had just crested\nthe ridge of the eastern hills."},{"no":3,"img":"assets/images/chapter_01/IMG-015.webp","pages":["屋敷の南面、家長の書斎では、\n祖父が朝の煙管を吹かしていた。\n煙管の灰がひとつ、\n火桶の縁にことりと落ちる。","祖父は何ごとかを思案する顔つきで、\nその灰を見つめている。\n父は、同じ書斎の片隅で、\n畳に手をついて控えていた。","祖父は煙を細く吐き、口を開く。\n「夜半に、娘が外へ出ようとしたそうな」"],"text":"屋敷の南面、家長の書斎では、\n祖父が朝の煙管を吹かしていた。\n煙管の灰がひとつ、\n火桶の縁にことりと落ちる。\n祖父は何ごとかを思案する顔つきで、\nその灰を見つめている。\n父は、同じ書斎の片隅で、\n畳に手をついて控えていた。\n祖父は煙を細く吐き、口を開く。\n「夜半に、娘が外へ出ようとしたそうな」","pages_en":["In the grandfather's study on the south side,\nthe old man drew his morning pipe.\nAsh dropped once,\nfaintly, onto the brazier's rim.","Grandfather stared at the ash,\nas if pondering something.\nIn a corner of the same room,\nthe father knelt with hands on the tatami.","Grandfather exhaled a thin ribbon of smoke\nand at last spoke.\n\"They say she tried to slip out\nin the night.\""],"text_en":"In the grandfather's study on the south side,\nthe old man drew his morning pipe.\nAsh dropped once,\nfaintly, onto the brazier's rim.\nGrandfather stared at the ash,\nas if pondering something.\nIn a corner of the same room,\nthe father knelt with hands on the tatami.\nGrandfather exhaled a thin ribbon of smoke\nand at last spoke.\n\"They say she tried to slip out\nin the night.\""},{"no":4,"img":"assets/images/chapter_01/IMG-016.webp","pages":["「番頭が、庭の籬の手前で、\n娘を押さえたそうじゃ。\nお主はなにか聞いておらぬか？」"],"text":"「番頭が、庭の籬の手前で、\n娘を押さえたそうじゃ。\nお主はなにか聞いておらぬか？」","pages_en":["\"The head clerk stopped her\nby the garden fence.\nHave you heard nothing of this?\""],"text_en":"\"The head clerk stopped her\nby the garden fence.\nHave you heard nothing of this?\""},{"no":5,"img":"assets/images/chapter_01/IMG-017.webp","pages":["父は応えなかった。\n畳の縁に置いた父の指が、\nわずかに白くなっている。\n父の喉が、ひとつ、確かに動いた。","祖父はその指を、長く見つめていた。\n煙管の灰が、もうひとつ火桶の縁に落ちる。\n父の額には、ごく薄く汗の珠が滲んでいた。"],"text":"父は応えなかった。\n畳の縁に置いた父の指が、\nわずかに白くなっている。\n父の喉が、ひとつ、確かに動いた。\n祖父はその指を、長く見つめていた。\n煙管の灰が、もうひとつ火桶の縁に落ちる。\n父の額には、ごく薄く汗の珠が滲んでいた。","pages_en":["The father made no reply.\nHis fingers, set on the tatami's edge,\nturned faintly white.\nHis throat moved once, unmistakably.","Grandfather watched that finger long.\nAnother speck fell to the brazier's rim.\nOn the father's brow, a fine sweat\nhad begun to gather."],"text_en":"The father made no reply.\nHis fingers, set on the tatami's edge,\nturned faintly white.\nHis throat moved once, unmistakably.\nGrandfather watched that finger long.\nAnother speck fell to the brazier's rim.\nOn the father's brow, a fine sweat\nhad begun to gather."},{"no":6,"img":"assets/images/chapter_01/IMG-018.webp","pages":["同じ刻、屋敷の北面の座牢では、\n娘が畳の上に座していた。","着物の肘のあたりに、昨夜の砂利の汚れが、\nうっすらと残る。座牢の格子戸越しに、\n廊下の朝の光が斜めに射し込んでいる。","光の縞が、昨夜の月光と同じ角度で、\n娘の頬を斜に切り取った。"],"text":"同じ刻、屋敷の北面の座牢では、\n娘が畳の上に座していた。\n着物の肘のあたりに、昨夜の砂利の汚れが、\nうっすらと残る。座牢の格子戸越しに、\n廊下の朝の光が斜めに射し込んでいる。\n光の縞が、昨夜の月光と同じ角度で、\n娘の頬を斜に切り取った。","pages_en":["At that same hour,\nin the Cell of the north wall,\nthe girl sat upon the tatami.","Faint traces of last night's grit\nclung to the sleeves of her robe.\nMorning light entered slantwise\nthrough the lattice from the hall.","The stripes fell at the same angle\nas the moonlight the night before,\ncutting her cheek in silver bands."],"text_en":"At that same hour,\nin the Cell of the north wall,\nthe girl sat upon the tatami.\nFaint traces of last night's grit\nclung to the sleeves of her robe.\nMorning light entered slantwise\nthrough the lattice from the hall.\nThe stripes fell at the same angle\nas the moonlight the night before,\ncutting her cheek in silver bands."},{"no":7,"img":"assets/images/chapter_01/IMG-019.webp","pages":["屋敷の塀の向こうでは、近隣の子らが\n追いかけっこをして遊んでいた。\n「次はあたしの番！」と声を張る子の頬は、\n朝の冷えで赤い。","子らは、塀の中の屋敷のことなど、\n何ひとつ知らずに走り回る。"],"text":"屋敷の塀の向こうでは、近隣の子らが\n追いかけっこをして遊んでいた。\n「次はあたしの番！」と声を張る子の頬は、\n朝の冷えで赤い。\n子らは、塀の中の屋敷のことなど、\n何ひとつ知らずに走り回る。","pages_en":["Beyond the manor wall, village children\nchased one another in play.\n\"My turn next!\" cried one,\nhis cheeks red with morning cold.","The children knew nothing\nof what lay within the walls,\nand ran on."],"text_en":"Beyond the manor wall, village children\nchased one another in play.\n\"My turn next!\" cried one,\nhis cheeks red with morning cold.\nThe children knew nothing\nof what lay within the walls,\nand ran on."},{"no":8,"img":"assets/images/chapter_01/IMG-020.webp","pages":["屋敷の中ほどの台所では、\n母が膳の支度を終えていた。\n膳の上には塩むすびと味噌の汁、\nそして青菜が一片である。","母はその膳を持ち、廊下を北へと歩いた。"],"text":"屋敷の中ほどの台所では、\n母が膳の支度を終えていた。\n膳の上には塩むすびと味噌の汁、\nそして青菜が一片である。\n母はその膳を持ち、廊下を北へと歩いた。","pages_en":["In the kitchen at the center of the manor,\nthe mother had finished the morning tray.\nUpon it lay a rice ball with salt,\nmiso soup, and a piece of greens.","She lifted the tray\nand walked north down the hall."],"text_en":"In the kitchen at the center of the manor,\nthe mother had finished the morning tray.\nUpon it lay a rice ball with salt,\nmiso soup, and a piece of greens.\nShe lifted the tray\nand walked north down the hall."},{"no":9,"img":"assets/images/chapter_01/IMG-021.webp","pages":["座牢の前まで来ると、母は格子戸の脇の\n小さな差し口を開き、\n膳を中へと押し入れた。\n娘の前に膳がそっと置かれた。"],"text":"座牢の前まで来ると、母は格子戸の脇の\n小さな差し口を開き、\n膳を中へと押し入れた。\n娘の前に膳がそっと置かれた。","pages_en":["At the Cell she opened the small hatch\nbeside the lattice\nand pushed the tray through.\nIt was placed gently before the girl."],"text_en":"At the Cell she opened the small hatch\nbeside the lattice\nand pushed the tray through.\nIt was placed gently before the girl."},{"no":10,"img":"assets/images/chapter_01/IMG-022.webp","pages":["「夜半に、廊下へ出てはなりませぬ」と、\n母は格子の向こうから一言だけ告げる。\n娘は応えなかった。\n母は差し口を閉ざし、廊下を戻ってゆく。","母の袂の影が、座牢の格子に一瞬だけ落ち、\nそれからすっと消えた。"],"text":"「夜半に、廊下へ出てはなりませぬ」と、\n母は格子の向こうから一言だけ告げる。\n娘は応えなかった。\n母は差し口を閉ざし、廊下を戻ってゆく。\n母の袂の影が、座牢の格子に一瞬だけ落ち、\nそれからすっと消えた。","pages_en":["\"You must not step into the hall at night,\"\nthe mother said through the lattice.\nThe girl gave no reply.\nThe hatch was closed. The mother withdrew.","The shadow of the mother's sleeve\nflickered once on the lattice,\nand then was gone."],"text_en":"\"You must not step into the hall at night,\"\nthe mother said through the lattice.\nThe girl gave no reply.\nThe hatch was closed. The mother withdrew.\nThe shadow of the mother's sleeve\nflickered once on the lattice,\nand then was gone."},{"no":11,"img":"assets/images/chapter_01/IMG-023.webp","pages":["膳の塩むすびの上には、\n昨夜の風が運んだのであろう、\n青葉が一片、はらりと落ちている。\n娘は青葉を指で拾い上げ葉の縁を見つめた。","葉の縁の冷えに、\nふと、幼き日の朝の記憶が重なる。\n霊柩が屋敷の前を渡るあの朝のこと。","母は娘の小さき指をそっと拳から解き、\n低く一度だけ、こう告げたものであった。\n「もう、その所作はなさるな」──"," 娘は青葉を膳の脇に置き、\n両手を膝の上で揃えたまま、\nしばらく動かずにいた。"],"text":"膳の塩むすびの上には、\n昨夜の風が運んだのであろう、\n青葉が一片、はらりと落ちている。\n娘は青葉を指で拾い上げ葉の縁を見つめた。\n葉の縁の冷えに、\nふと、幼き日の朝の記憶が重なる。\n霊柩が屋敷の前を渡るあの朝のこと。\n母は娘の小さき指をそっと拳から解き、\n低く一度だけ、こう告げたものであった。\n「もう、その所作はなさるな」──\n 娘は青葉を膳の脇に置き、\n両手を膝の上で揃えたまま、\nしばらく動かずにいた。","pages_en":["Upon the salted rice ball on the tray\nlay a single fallen leaf,\nborne perhaps by the night wind.\nThe girl picked it up by its edge.","The chill of the leaf's edge\nbrought back, unbidden,\na morning from her childhood ─\nthe morning a funeral bier passed the manor.","Her mother had gently unfolded\nher small fingers from her fists,\nand said only, once, in a low voice:\n\"You must never do that again.\"","The girl set the leaf beside the tray,\nfolded her hands upon her knees,\nand for a long while,\ndid not move."],"text_en":"Upon the salted rice ball on the tray\nlay a single fallen leaf,\nborne perhaps by the night wind.\nThe girl picked it up by its edge.\nThe chill of the leaf's edge\nbrought back, unbidden,\na morning from her childhood ─\nthe morning a funeral bier passed the manor.\nHer mother had gently unfolded\nher small fingers from her fists,\nand said only, once, in a low voice:\n\"You must never do that again.\"\nThe girl set the leaf beside the tray,\nfolded her hands upon her knees,\nand for a long while,\ndid not move."}]},{"title":"第三章 ─ 廊下の声と書斎の対峙","folder":"chapter_02","taps":[{"no":1,"img":"assets/images/chapter_02/IMG-024.webp","pages":["初めて座牢を抜け出したあの夜以来、\n娘は折を見て、夜ごと格子戸の錠を\nひそかに開けるようになっていた。"],"text":"初めて座牢を抜け出したあの夜以来、\n娘は折を見て、夜ごと格子戸の錠を\nひそかに開けるようになっていた。","pages_en":["Since her first escape from the Cell,\nthe girl had come, at intervals,\nto unlock the lattice\nquietly in the dead of night."],"text_en":"Since her first escape from the Cell,\nthe girl had come, at intervals,\nto unlock the lattice\nquietly in the dead of night."},{"no":2,"img":"assets/images/chapter_02/IMG-025.webp","pages":["されど願いはついぞ叶わず、決まって\nもう一歩というところで、屋敷の者の手に\n取り押さえられて来たのである。"],"text":"されど願いはついぞ叶わず、決まって\nもう一歩というところで、屋敷の者の手に\n取り押さえられて来たのである。","pages_en":["Yet her wish was never granted.\nAlways, at one step short,\nsomeone of the house would seize her\nand return her to the Cell."],"text_en":"Yet her wish was never granted.\nAlways, at one step short,\nsomeone of the house would seize her\nand return her to the Cell."},{"no":3,"img":"assets/images/chapter_02/IMG-026.webp","pages":["そんなある夜、祖父の書斎で、\n煙管の音が短く跳ねた。"],"text":"そんなある夜、祖父の書斎で、\n煙管の音が短く跳ねた。","pages_en":["On one such night, from the study,\ncame the short crack of a pipe."],"text_en":"On one such night, from the study,\ncame the short crack of a pipe."},{"no":4,"img":"assets/images/chapter_02/IMG-027.webp","pages":["祖父は父を畳の縁に座らせて、\n低く詰問している。\n「娘が抜け出そうとするのは、\nお前が見張りを緩めておるためじゃ」","「家督を継ぐ身が、夜半にひとりの娘の\n動きすら捌けぬとは、何たることぞ」\n父は応えを返さなかった。","畳に置いた両の手が、\n震えぬよう力を入れているのが、\n襖の影越しにも分かる。","「……面目次第もござりませぬ。\nお父様の御諭し、肝に銘じまする」\n父はようやくそれだけを絞り出す。\n声は、咽の奥で湿っていた。"],"text":"祖父は父を畳の縁に座らせて、\n低く詰問している。\n「娘が抜け出そうとするのは、\nお前が見張りを緩めておるためじゃ」\n「家督を継ぐ身が、夜半にひとりの娘の\n動きすら捌けぬとは、何たることぞ」\n父は応えを返さなかった。\n畳に置いた両の手が、\n震えぬよう力を入れているのが、\n襖の影越しにも分かる。\n「……面目次第もござりませぬ。\nお父様の御諭し、肝に銘じまする」\n父はようやくそれだけを絞り出す。\n声は、咽の奥で湿っていた。","pages_en":["Grandfather had seated the father\nat the edge of the tatami,\nand was pressing him low.\n\"She tries to slip out because","your guard is slack.\nA man meant to inherit this house,\nunable to master the movements\nof one girl in the night ─ what is this?\"","The father gave no reply.\nHis hands, pressed to the tatami,\nstrove not to tremble ─\nvisible even through the shadow of the door.","\"…I have no words to defend myself.\nI shall take Father's instruction\ndeep into my heart.\"\nHis voice came damp from his throat."],"text_en":"Grandfather had seated the father\nat the edge of the tatami,\nand was pressing him low.\n\"She tries to slip out because\nyour guard is slack.\nA man meant to inherit this house,\nunable to master the movements\nof one girl in the night ─ what is this?\"\nThe father gave no reply.\nHis hands, pressed to the tatami,\nstrove not to tremble ─\nvisible even through the shadow of the door.\n\"…I have no words to defend myself.\nI shall take Father's instruction\ndeep into my heart.\"\nHis voice came damp from his throat."},{"no":5,"img":"assets/images/chapter_02/IMG-028.webp","pages":["廊下のさらに奥では、叔父が立ち止まり、\n書斎の方を一度だけ見たあと、\n襖の蔭にすっと身を引いた。","祖父の煙管の音だけが、\n屋敷の闇をしばらく渡っていく。"],"text":"廊下のさらに奥では、叔父が立ち止まり、\n書斎の方を一度だけ見たあと、\n襖の蔭にすっと身を引いた。\n祖父の煙管の音だけが、\n屋敷の闇をしばらく渡っていく。","pages_en":["Farther down the hall, the uncle paused.\nHe cast one glance toward the study,\nthen quietly withdrew\nbehind the sliding door.","Only the sound of Grandfather's pipe\ncarried through the darkness of the house."],"text_en":"Farther down the hall, the uncle paused.\nHe cast one glance toward the study,\nthen quietly withdrew\nbehind the sliding door.\nOnly the sound of Grandfather's pipe\ncarried through the darkness of the house."},{"no":6,"img":"assets/images/chapter_02/IMG-029.webp","pages":["夜更け、母は父の寝間に\n酒杯をひとつ忍ばせて、廊下を歩いた。\n父は寝所の障子に背を向け、\n酒杯を黙って受け取る。"],"text":"夜更け、母は父の寝間に\n酒杯をひとつ忍ばせて、廊下を歩いた。\n父は寝所の障子に背を向け、\n酒杯を黙って受け取る。","pages_en":["Deep in the night, the mother\ncarried a small cup of sake\ndown the hall to her husband's chamber.\nHe took it without turning to face her."],"text_en":"Deep in the night, the mother\ncarried a small cup of sake\ndown the hall to her husband's chamber.\nHe took it without turning to face her."},{"no":7,"img":"assets/images/chapter_02/IMG-030.webp","pages":["母の指がほんの一瞬、父の指に触れた。\n父はその指を、振り解きもせず、\n握り返しもしなかった。"],"text":"母の指がほんの一瞬、父の指に触れた。\n父はその指を、振り解きもせず、\n握り返しもしなかった。","pages_en":["Her fingers, for a moment,\ntouched his.\nHe neither shook them away\nnor closed his own around them."],"text_en":"Her fingers, for a moment,\ntouched his.\nHe neither shook them away\nnor closed his own around them."},{"no":8,"img":"assets/images/chapter_02/IMG-031.webp","pages":["座牢では、娘が桐の小箱を膝に置き、\n螺鈿の貝殻をそっと撫でている。\n幼き日、叔父より授かったものであった。","月光が高窓の格子をくぐり、\n貝殻の縁を淡く光らせていた。"],"text":"座牢では、娘が桐の小箱を膝に置き、\n螺鈿の貝殻をそっと撫でている。\n幼き日、叔父より授かったものであった。\n月光が高窓の格子をくぐり、\n貝殻の縁を淡く光らせていた。","pages_en":["In the Cell, the girl held a paulownia box\nupon her lap\nand stroked, softly,\nthe mother-of-pearl shell within.","It had been given her by the uncle,\nin her childhood days.\nMoonlight through the high lattice\nlit the shell's edge pale."],"text_en":"In the Cell, the girl held a paulownia box\nupon her lap\nand stroked, softly,\nthe mother-of-pearl shell within.\nIt had been given her by the uncle,\nin her childhood days.\nMoonlight through the high lattice\nlit the shell's edge pale."}]},{"title":"第四章 ─ 商人の影","folder":"chapter_03","taps":[{"no":1,"img":"assets/images/chapter_03/IMG-032.webp","pages":["昼下がりであった。\n屋敷の正面の玄関で、\n女中が振袖の商人をひとり、\n座敷へと迎え入れる声を上げた。"],"text":"昼下がりであった。\n屋敷の正面の玄関で、\n女中が振袖の商人をひとり、\n座敷へと迎え入れる声を上げた。","pages_en":["It was afternoon.\nAt the front entrance of the manor,\na maid called out as she welcomed\na merchant in a bright kimono."],"text_en":"It was afternoon.\nAt the front entrance of the manor,\na maid called out as she welcomed\na merchant in a bright kimono."},{"no":2,"img":"assets/images/chapter_03/IMG-033.webp","pages":["商人は通いの行商人であり、\n東京の景物を頻りに語る男であった。\n座敷では、父が床柱に背を預けて、\n商人の広げる反物を眺めている。","「東京の女子は皆、振袖を着て、\n夜店を歩いておりますのじゃ」\n三味の音、夜店の灯、人の波 ──","商人の語る東京の景は、\nどれも父にとっては縁遠い色をしている。\n父は反物の縁を指で撫で、一言だけ返した。\n「常の反物でよい」","商人は二、三、世辞を残し、\n座敷を辞して玄関へと戻っていく。"],"text":"商人は通いの行商人であり、\n東京の景物を頻りに語る男であった。\n座敷では、父が床柱に背を預けて、\n商人の広げる反物を眺めている。\n「東京の女子は皆、振袖を着て、\n夜店を歩いておりますのじゃ」\n三味の音、夜店の灯、人の波 ──\n商人の語る東京の景は、\nどれも父にとっては縁遠い色をしている。\n父は反物の縁を指で撫で、一言だけ返した。\n「常の反物でよい」\n商人は二、三、世辞を残し、\n座敷を辞して玄関へと戻っていく。","pages_en":["The merchant was a traveling peddler,\nfull of talk of Tokyo's amusements.\nIn the parlor, the father leaned\nagainst the alcove post, watching.","\"The women of Tokyo, all of them,\nwear such robes as this,\nand stroll among the night stalls,\"\nsaid the merchant.","The scenes he spoke of ─\nthe shamisen, the stall lanterns,\nthe waves of people ─\nwere all colors distant from the father.","The father traced the fabric's edge\nwith his finger,\nand replied with one line only:\n\"The usual cloth will suffice.\"","The merchant left flatteries, one or two,\nand withdrew from the parlor\ntoward the entrance."],"text_en":"The merchant was a traveling peddler,\nfull of talk of Tokyo's amusements.\nIn the parlor, the father leaned\nagainst the alcove post, watching.\n\"The women of Tokyo, all of them,\nwear such robes as this,\nand stroll among the night stalls,\"\nsaid the merchant.\nThe scenes he spoke of ─\nthe shamisen, the stall lanterns,\nthe waves of people ─\nwere all colors distant from the father.\nThe father traced the fabric's edge\nwith his finger,\nand replied with one line only:\n\"The usual cloth will suffice.\"\nThe merchant left flatteries, one or two,\nand withdrew from the parlor\ntoward the entrance."},{"no":3,"img":"assets/images/chapter_03/IMG-034.webp","pages":["廊下を商人とすれ違うようにして、\n若い男がひとり、書物を抱えて\n屋敷の奥へと歩いて行った。数月前から\n屋敷の手伝いに入っている書生である。"],"text":"廊下を商人とすれ違うようにして、\n若い男がひとり、書物を抱えて\n屋敷の奥へと歩いて行った。数月前から\n屋敷の手伝いに入っている書生である。","pages_en":["As the merchant left,\na young man walked past him,\nbooks in his arms,\ntoward the depths of the manor.","He was a student\nwho had joined the household\nsome months prior\nto assist with its affairs."],"text_en":"As the merchant left,\na young man walked past him,\nbooks in his arms,\ntoward the depths of the manor.\nHe was a student\nwho had joined the household\nsome months prior\nto assist with its affairs."},{"no":4,"img":"assets/images/chapter_03/IMG-035.webp","pages":["廊下のさらに奥では、叔父が再び姿を見せ、\n書生の背をじっと見送っていた。\n叔父は、客のある折には決して\n座敷へ顔を出さぬ人であるらしい。","座敷を辞した父は、\n廊下で叔父と一瞬だけ目を合わせる。\n叔父は何も言わず、すっと顔をそむけて、\n奥座敷の方へと立ち去った。"],"text":"廊下のさらに奥では、叔父が再び姿を見せ、\n書生の背をじっと見送っていた。\n叔父は、客のある折には決して\n座敷へ顔を出さぬ人であるらしい。\n座敷を辞した父は、\n廊下で叔父と一瞬だけ目を合わせる。\n叔父は何も言わず、すっと顔をそむけて、\n奥座敷の方へと立ち去った。","pages_en":["Farther down the hall,\nthe uncle appeared once more\nand watched the student's back\nwith a fixed gaze.","When guests came, it seemed,\nthe uncle never showed his face\nin the parlor.\nThe father, leaving the room,","met the uncle's eye for one instant.\nThe uncle said nothing,\nturned his face away,\nand departed toward the inner parlor."],"text_en":"Farther down the hall,\nthe uncle appeared once more\nand watched the student's back\nwith a fixed gaze.\nWhen guests came, it seemed,\nthe uncle never showed his face\nin the parlor.\nThe father, leaving the room,\nmet the uncle's eye for one instant.\nThe uncle said nothing,\nturned his face away,\nand departed toward the inner parlor."},{"no":5,"img":"assets/images/chapter_03/IMG-036.webp","pages":["座牢では、娘が高窓の下に立っていた。\n高窓の格子の隙からは、商人の去る車輪の\n音だけが、塀越しにわずかに届く。"],"text":"座牢では、娘が高窓の下に立っていた。\n高窓の格子の隙からは、商人の去る車輪の\n音だけが、塀越しにわずかに届く。","pages_en":["In the Cell, the girl stood\nbeneath the high window.\nThrough the lattice she caught only\nthe wheels of the merchant's cart","carrying away beyond the wall."],"text_en":"In the Cell, the girl stood\nbeneath the high window.\nThrough the lattice she caught only\nthe wheels of the merchant's cart\ncarrying away beyond the wall."},{"no":6,"img":"assets/images/chapter_03/IMG-037.webp","pages":["娘の掌の中では、桐の小箱から取り出した\n螺鈿の貝殻が、淡く色を放つ。\n光の縁は、いま塀の外を渡るはずの\n春の陽射しと同じ色をしているのであった。"],"text":"娘の掌の中では、桐の小箱から取り出した\n螺鈿の貝殻が、淡く色を放つ。\n光の縁は、いま塀の外を渡るはずの\n春の陽射しと同じ色をしているのであった。","pages_en":["In her palm, the mother-of-pearl shell,\ndrawn from the paulownia box,\nglowed faintly.\nThe edge of that light bore the same hue","as the spring sunlight\nnow crossing beyond the wall."],"text_en":"In her palm, the mother-of-pearl shell,\ndrawn from the paulownia box,\nglowed faintly.\nThe edge of that light bore the same hue\nas the spring sunlight\nnow crossing beyond the wall."}]},{"title":"第五章 ─ 測る眼","folder":"chapter_04","taps":[{"no":1,"img":"assets/images/chapter_04/IMG-038.webp","pages":["同じ月の夜、座牢の錠は\n再び娘の指の下で外れた。\n娘は着物の裾を膝で握り、\n廊下の闇を奥へと進む。"],"text":"同じ月の夜、座牢の錠は\n再び娘の指の下で外れた。\n娘は着物の裾を膝で握り、\n廊下の闇を奥へと進む。","pages_en":["That same month, on another night,\nthe Cell's lock again yielded\nbeneath the girl's finger.\nShe gathered the hem of her robe","and pressed on into the hall's darkness."],"text_en":"That same month, on another night,\nthe Cell's lock again yielded\nbeneath the girl's finger.\nShe gathered the hem of her robe\nand pressed on into the hall's darkness."},{"no":2,"img":"assets/images/chapter_04/IMG-039.webp","pages":["廊下を抜け――、\n玄関の三和土に降り立った娘の肩を、\n太き手が後ろから掴んだ。\n番頭であった。","番頭は屋敷の玄関口を\n夜ごと巡回する役であり、\nその手はやすやすと娘の肩を抑え込む。"],"text":"廊下を抜け――、\n玄関の三和土に降り立った娘の肩を、\n太き手が後ろから掴んだ。\n番頭であった。\n番頭は屋敷の玄関口を\n夜ごと巡回する役であり、\nその手はやすやすと娘の肩を抑え込む。","pages_en":["She passed through the corridor ─\nand as she stepped down\nonto the entrance stones,\na thick hand seized her shoulder.","It was the head clerk,\nwhose duty was to patrol\nthe manor's entrance in the night.\nHis grip pinned her without effort."],"text_en":"She passed through the corridor ─\nand as she stepped down\nonto the entrance stones,\na thick hand seized her shoulder.\nIt was the head clerk,\nwhose duty was to patrol\nthe manor's entrance in the night.\nHis grip pinned her without effort."},{"no":3,"img":"assets/images/chapter_04/IMG-040.webp","pages":["騒ぎを聞きつけて、屋敷の者が\n次々と廊下に集まってきた。\n父は奥座敷の障子の蔭から、娘の方を\n一度だけ見て、静かに部屋の奥へ退いた。"],"text":"騒ぎを聞きつけて、屋敷の者が\n次々と廊下に集まってきた。\n父は奥座敷の障子の蔭から、娘の方を\n一度だけ見て、静かに部屋の奥へ退いた。","pages_en":["Roused by the noise,\nmembers of the household\ngathered one by one in the hall.\nThe father, from behind the study door,","cast one glance at the girl,\nthen quietly withdrew into the room."],"text_en":"Roused by the noise,\nmembers of the household\ngathered one by one in the hall.\nThe father, from behind the study door,\ncast one glance at the girl,\nthen quietly withdrew into the room."},{"no":4,"img":"assets/images/chapter_04/IMG-041.webp","pages":["廊下の隅には、若い男がひとり、\n書物を脇に挟んだまま立っていた。\n書生である。"],"text":"廊下の隅には、若い男がひとり、\n書物を脇に挟んだまま立っていた。\n書生である。","pages_en":["At the edge of the hall\nstood a young man,\na book pressed under his arm.\nIt was the student."],"text_en":"At the edge of the hall\nstood a young man,\na book pressed under his arm.\nIt was the student."},{"no":5,"img":"assets/images/chapter_04/IMG-042.webp","pages":["書生は、娘の姿を紙の上に\n写し取るような眼差しで見つめていた。\nその眼差しに、娘は思わず身を竦めた。"],"text":"書生は、娘の姿を紙の上に\n写し取るような眼差しで見つめていた。\nその眼差しに、娘は思わず身を竦めた。","pages_en":["He gazed at the girl\nas though writing her likeness\nonto paper.\nUnder his gaze, she flinched instinctively."],"text_en":"He gazed at the girl\nas though writing her likeness\nonto paper.\nUnder his gaze, she flinched instinctively."},{"no":6,"img":"assets/images/chapter_04/IMG-043.webp","pages":["廊下のさらに奥では、叔父がやはり、\n人々の輪には加わらず、\n柱に背を寄せたまま目を逸らしている。","そうこうしているうちに、\n娘は番頭の手によって、再び座牢へと\n連れ戻された。"],"text":"廊下のさらに奥では、叔父がやはり、\n人々の輪には加わらず、\n柱に背を寄せたまま目を逸らしている。\nそうこうしているうちに、\n娘は番頭の手によって、再び座牢へと\n連れ戻された。","pages_en":["Farther still down the hall,\nthe uncle again did not join the crowd,\nbut leaned against a post,\nhis eyes turned aside.","Meanwhile, the head clerk led the girl\nback to the Cell once more."],"text_en":"Farther still down the hall,\nthe uncle again did not join the crowd,\nbut leaned against a post,\nhis eyes turned aside.\nMeanwhile, the head clerk led the girl\nback to the Cell once more."},{"no":7,"img":"assets/images/chapter_04/IMG-044.webp","pages":["その夜、母は座牢に膳を運んだ折、\n格子戸の脇の小窓越しに、言葉をかけた。\n「あの書生には、お気をつけなされませ」","「お前様の挙措を、\n長く目で追うておりました」"],"text":"その夜、母は座牢に膳を運んだ折、\n格子戸の脇の小窓越しに、言葉をかけた。\n「あの書生には、お気をつけなされませ」\n「お前様の挙措を、\n長く目で追うておりました」","pages_en":["That night, when the mother\nbrought a tray to the Cell,\nshe spoke through the small hatch:\n\"Be wary of that student.\"","\"He has followed your every movement\nwith his eyes,\nfor a long time now.\""],"text_en":"That night, when the mother\nbrought a tray to the Cell,\nshe spoke through the small hatch:\n\"Be wary of that student.\"\n\"He has followed your every movement\nwith his eyes,\nfor a long time now.\""},{"no":8,"img":"assets/images/chapter_04/IMG-045.webp","pages":["母はそれだけを告げて、\n座牢の格子戸を閉ざしてゆく。\n母の袂の影が、廊下の畳の上を、\nひとすじだけ揺らして消えた。","座牢にひとり残された娘は、\nふと、畳の縁の朱に気がついた。"],"text":"母はそれだけを告げて、\n座牢の格子戸を閉ざしてゆく。\n母の袂の影が、廊下の畳の上を、\nひとすじだけ揺らして消えた。\n座牢にひとり残された娘は、\nふと、畳の縁の朱に気がついた。","pages_en":["The mother said only that,\nand closed the lattice.\nThe shadow of her sleeve trembled once\non the hallway tatami and vanished.","Left alone in the Cell,\nthe girl noticed a crimson stain\non the edge of the tatami."],"text_en":"The mother said only that,\nand closed the lattice.\nThe shadow of her sleeve trembled once\non the hallway tatami and vanished.\nLeft alone in the Cell,\nthe girl noticed a crimson stain\non the edge of the tatami."},{"no":9,"img":"assets/images/chapter_04/IMG-046.webp","pages":["子供の掌ほどの朱の手形がひとつ。\nそれがいつから其処にあるのか、\n娘には思い出せなかった。","朱の縁に指を伸ばした、その時、\n何者にか見られているという感覚が、\nふいに立ち昇ってきた。\n感覚の主は見えない。","されども娘は、朱の縁から、\n手を離さなかった。否、離せなかった。\nその朱の手形には娘を引き付ける、\n奇妙な力が宿っているようであった。"],"text":"子供の掌ほどの朱の手形がひとつ。\nそれがいつから其処にあるのか、\n娘には思い出せなかった。\n朱の縁に指を伸ばした、その時、\n何者にか見られているという感覚が、\nふいに立ち昇ってきた。\n感覚の主は見えない。\nされども娘は、朱の縁から、\n手を離さなかった。否、離せなかった。\nその朱の手形には娘を引き付ける、\n奇妙な力が宿っているようであった。","pages_en":["A small vermilion handprint,\nthe size of a child's palm.\nWhen it had first appeared there,\nthe girl could not recall.","As her finger reached toward its edge,\na sensation of being watched\nrose from somewhere unseen.\nShe could not tell its source.","Yet she did not lift her hand ─\nnor could she.\nSome strange power in that print\nseemed to hold her there."],"text_en":"A small vermilion handprint,\nthe size of a child's palm.\nWhen it had first appeared there,\nthe girl could not recall.\nAs her finger reached toward its edge,\na sensation of being watched\nrose from somewhere unseen.\nShe could not tell its source.\nYet she did not lift her hand ─\nnor could she.\nSome strange power in that print\nseemed to hold her there."}]},{"title":"第六章 ─ 会釈と祭壇の影","folder":"chapter_05","taps":[{"no":1,"img":"assets/images/chapter_05/IMG-047.webp","pages":["翌朝、屋敷の北の廊下を、\n叔父がゆっくりと歩いていた。"],"text":"翌朝、屋敷の北の廊下を、\n叔父がゆっくりと歩いていた。","pages_en":["The next morning,\nthe uncle walked slowly\ndown the northern hallway of the manor."],"text_en":"The next morning,\nthe uncle walked slowly\ndown the northern hallway of the manor."},{"no":2,"img":"assets/images/chapter_05/IMG-048.webp","pages":["叔父の手には、膳が抱えられている。\n屋敷において叔父の膳を運ぶ役は、\n母をおいて他にはひとりもおらぬ。\nしかし、今日は母の姿が見えなかった。","その朝は、叔父は自らの膳を\n自らの手で運んでいた。\nすると――、"],"text":"叔父の手には、膳が抱えられている。\n屋敷において叔父の膳を運ぶ役は、\n母をおいて他にはひとりもおらぬ。\nしかし、今日は母の姿が見えなかった。\nその朝は、叔父は自らの膳を\n自らの手で運んでいた。\nすると――、","pages_en":["A tray was in his hands.\nThe carrying of the uncle's tray\nhad always fallen to the mother alone.\nBut this morning she was not to be seen.","That morning, the uncle carried\nhis own tray with his own hands.\nAnd then ─"],"text_en":"A tray was in his hands.\nThe carrying of the uncle's tray\nhad always fallen to the mother alone.\nBut this morning she was not to be seen.\nThat morning, the uncle carried\nhis own tray with his own hands.\nAnd then ─"},{"no":3,"img":"assets/images/chapter_05/IMG-049.webp","pages":["廊下の彼方から叔母の鋭い声が飛んできた。\n「弟嫁、何をぐずぐずしておられるのじゃ」\n叔母に睨みつけられた母は、\nただ俯いたまま、叔母の後に続くのだった。"],"text":"廊下の彼方から叔母の鋭い声が飛んできた。\n「弟嫁、何をぐずぐずしておられるのじゃ」\n叔母に睨みつけられた母は、\nただ俯いたまま、叔母の後に続くのだった。","pages_en":["From the far end of the hall came\nthe sharp voice of the aunt:\n\"Sister-in-law, why are you dawdling?\"\nGlared at by the aunt, the mother","merely bowed her head\nand followed behind her."],"text_en":"From the far end of the hall came\nthe sharp voice of the aunt:\n\"Sister-in-law, why are you dawdling?\"\nGlared at by the aunt, the mother\nmerely bowed her head\nand followed behind her."},{"no":4,"img":"assets/images/chapter_05/IMG-050.webp","pages":["叔父は座牢の前まで来ると、\n格子戸の方をちらりと一度だけ見た。\n座牢の中の娘は、その視線を受けて、\n格子越しに頭を深く下げる。","叔父は会釈を返すでもなく、\nそのまま廊下を遠ざかってゆく。"],"text":"叔父は座牢の前まで来ると、\n格子戸の方をちらりと一度だけ見た。\n座牢の中の娘は、その視線を受けて、\n格子越しに頭を深く下げる。\n叔父は会釈を返すでもなく、\nそのまま廊下を遠ざかってゆく。","pages_en":["Reaching the Cell, the uncle\ncast one glance toward the lattice.\nWithin, the girl received his gaze\nand bowed low through the bars.","The uncle did not return the bow,\nbut walked on down the hall."],"text_en":"Reaching the Cell, the uncle\ncast one glance toward the lattice.\nWithin, the girl received his gaze\nand bowed low through the bars.\nThe uncle did not return the bow,\nbut walked on down the hall."},{"no":5,"img":"assets/images/chapter_05/IMG-051.webp","pages":["角を曲がる手前で、叔父は一拍だけ、\nその場に立ち止まった。それから、\n奥座敷の方へとそのまま消えていった。","叔父の姿が消えた後、座牢の娘は、\n高窓の方へ顔を向ける。"],"text":"角を曲がる手前で、叔父は一拍だけ、\nその場に立ち止まった。それから、\n奥座敷の方へとそのまま消えていった。\n叔父の姿が消えた後、座牢の娘は、\n高窓の方へ顔を向ける。","pages_en":["Just before the corner,\nhe paused for one beat,\nthen vanished\ntoward the inner parlor.","After the uncle disappeared,\nthe girl turned her face\ntoward the high window."],"text_en":"Just before the corner,\nhe paused for one beat,\nthen vanished\ntoward the inner parlor.\nAfter the uncle disappeared,\nthe girl turned her face\ntoward the high window."},{"no":6,"img":"assets/images/chapter_05/IMG-052.webp","pages":["高窓の格子の隙からは、\n屋敷の祭壇がわずかに望めた。\n祭壇の前では、ひとりの男が、\n燈明の灯をひとつ、整えている。"],"text":"高窓の格子の隙からは、\n屋敷の祭壇がわずかに望めた。\n祭壇の前では、ひとりの男が、\n燈明の灯をひとつ、整えている。","pages_en":["Through the lattice she could just see\nthe manor's altar.\nBefore it, a man was quietly\ntending a votive lamp."],"text_en":"Through the lattice she could just see\nthe manor's altar.\nBefore it, a man was quietly\ntending a votive lamp."},{"no":7,"img":"assets/images/chapter_05/IMG-053.webp","pages":["父が妾に産ませた、腹違いの兄である。\n家の祭祀の手入れを、ひとりで\n任されている人であった。"],"text":"父が妾に産ませた、腹違いの兄である。\n家の祭祀の手入れを、ひとりで\n任されている人であった。","pages_en":["He was the elder brother,\nborn of a concubine to the father.\nAlone he had been entrusted\nwith the care of the family shrine."],"text_en":"He was the elder brother,\nborn of a concubine to the father.\nAlone he had been entrusted\nwith the care of the family shrine."},{"no":8,"img":"assets/images/chapter_05/IMG-054.webp","pages":["兄は誰とも口を利かず、\nただ燈明の灯をひとつ整えると、\n奥の納屋の方へと去っていく。屋敷の者は、\nその背に目を向けようとはしない。"],"text":"兄は誰とも口を利かず、\nただ燈明の灯をひとつ整えると、\n奥の納屋の方へと去っていく。屋敷の者は、\nその背に目を向けようとはしない。","pages_en":["The elder brother spoke to no one.\nHaving tended the lamp,\nhe departed toward the storehouse.\nNo one turned to watch him go."],"text_en":"The elder brother spoke to no one.\nHaving tended the lamp,\nhe departed toward the storehouse.\nNo one turned to watch him go."},{"no":9,"img":"assets/images/chapter_05/IMG-055.webp","pages":["座牢の娘はふと、\n叔父の歩みと他の家族の歩みとが、\n屋敷の中で別の調子を持ち始めていることに\n気がついた。"],"text":"座牢の娘はふと、\n叔父の歩みと他の家族の歩みとが、\n屋敷の中で別の調子を持ち始めていることに\n気がついた。","pages_en":["The girl noticed, then,\nthat the uncle's step\nand the steps of the rest of the family\nhad begun to keep different time."],"text_en":"The girl noticed, then,\nthat the uncle's step\nand the steps of the rest of the family\nhad begun to keep different time."},{"no":10,"img":"assets/images/chapter_05/IMG-056.webp","pages":["祭壇の前から去ってゆく兄の背中もまた、\nその調子のどれにも\n属していないのであった。"],"text":"祭壇の前から去ってゆく兄の背中もまた、\nその調子のどれにも\n属していないのであった。","pages_en":["And the back of the elder brother,\nleaving the altar behind,\nbelonged to none of those\nrhythms either."],"text_en":"And the back of the elder brother,\nleaving the altar behind,\nbelonged to none of those\nrhythms either."}]},{"title":"第七章 ─ 障子越しの問い","folder":"chapter_06","taps":[{"no":1,"img":"assets/images/chapter_06/IMG-057.webp","pages":["数日が過ぎた。\n夜更けの座牢に、ひとつの影が静かに映る。"],"text":"数日が過ぎた。\n夜更けの座牢に、ひとつの影が静かに映る。","pages_en":["Several days had passed.\nDeep in the night at the Cell,\na single shadow quietly fell\nupon the paper of the door."],"text_en":"Several days had passed.\nDeep in the night at the Cell,\na single shadow quietly fell\nupon the paper of the door."},{"no":2,"img":"assets/images/chapter_06/IMG-058.webp","pages":["障子の向こうの人物は、灯を携えたまま、\nしばらく身じろぎを見せない。\nやがて、低く抑えた声が、\n障子越しに座牢の中へと届いた。","「書生にござります」"],"text":"障子の向こうの人物は、灯を携えたまま、\nしばらく身じろぎを見せない。\nやがて、低く抑えた声が、\n障子越しに座牢の中へと届いた。\n「書生にござります」","pages_en":["The figure beyond the door\nheld a lantern, and for a long while\ndid not move.\nAt last a low voice, held down,","carried through the door\ninto the Cell:\n\"It is the student.\""],"text_en":"The figure beyond the door\nheld a lantern, and for a long while\ndid not move.\nAt last a low voice, held down,\ncarried through the door\ninto the Cell:\n\"It is the student.\""},{"no":3,"img":"assets/images/chapter_06/IMG-059.webp","pages":["座牢の娘は、布団の上で身を起こす。\n先夜、娘の姿を眼で写し取った、\nあの若い男の声であった。","「お前様の試みを、私はもう三度、\n見ましてござります」\n障子越しの声は、なおも続いた。\n「何故、外を望まれるのですか」"],"text":"座牢の娘は、布団の上で身を起こす。\n先夜、娘の姿を眼で写し取った、\nあの若い男の声であった。\n「お前様の試みを、私はもう三度、\n見ましてござります」\n障子越しの声は、なおも続いた。\n「何故、外を望まれるのですか」","pages_en":["Within, the girl rose from her bedding.\nIt was the voice of the young man\nwhose eyes had traced her form\non that earlier night.","\"I have watched your attempts\nthree times now,\" the voice continued.\n\"Why do you seek the outside?\""],"text_en":"Within, the girl rose from her bedding.\nIt was the voice of the young man\nwhose eyes had traced her form\non that earlier night.\n\"I have watched your attempts\nthree times now,\" the voice continued.\n\"Why do you seek the outside?\""},{"no":4,"img":"assets/images/chapter_06/IMG-060.webp","pages":["座牢の娘は、しばし沈黙を返す。\nやがて、声をひとつ絞り出した。\n「別の空の色を見たいのでござります」\n障子の影は、ゆっくりと頷いた。"],"text":"座牢の娘は、しばし沈黙を返す。\nやがて、声をひとつ絞り出した。\n「別の空の色を見たいのでござります」\n障子の影は、ゆっくりと頷いた。","pages_en":["The girl gave silence, at first.\nThen at last she pressed out a voice:\n\"To see the color of another sky.\"\nThe shadow of the door slowly nodded."],"text_en":"The girl gave silence, at first.\nThen at last she pressed out a voice:\n\"To see the color of another sky.\"\nThe shadow of the door slowly nodded."},{"no":5,"img":"assets/images/chapter_06/IMG-061.webp","pages":["「座牢の錠は、私が日中のうちに\n細工をしておきまする。\n番犬には、薬を仕込みましょう。\n今度の月の昏き夜に、私と共に……」"],"text":"「座牢の錠は、私が日中のうちに\n細工をしておきまする。\n番犬には、薬を仕込みましょう。\n今度の月の昏き夜に、私と共に……」","pages_en":["\"I shall tamper with the lock\nduring the daylight hours,\nand drug the watchdog.\nOn the next moonless night, with me…\""],"text_en":"\"I shall tamper with the lock\nduring the daylight hours,\nand drug the watchdog.\nOn the next moonless night, with me…\""},{"no":6,"img":"assets/images/chapter_06/IMG-062.webp","pages":["同じ夜更け、静けさに包まれた座敷では、\n父がひとり酒杯を傾けていた。\n盃の縁に映る父の顔は、平生よりも一層、\n青ざめている。"],"text":"同じ夜更け、静けさに包まれた座敷では、\n父がひとり酒杯を傾けていた。\n盃の縁に映る父の顔は、平生よりも一層、\n青ざめている。","pages_en":["That same night, in the parlor,\nthe father sat alone,\ntilting a sake cup.\nHis reflection in its rim","was paler than usual."],"text_en":"That same night, in the parlor,\nthe father sat alone,\ntilting a sake cup.\nHis reflection in its rim\nwas paler than usual."},{"no":7,"img":"assets/images/chapter_06/IMG-063.webp","pages":["障子の向こうより――、\n書生の声が遠く流れてくるのを、\n父は確かに聞いていた。だが、\n父は盃の口に当てたまま何も言わなかった。"],"text":"障子の向こうより――、\n書生の声が遠く流れてくるのを、\n父は確かに聞いていた。だが、\n父は盃の口に当てたまま何も言わなかった。","pages_en":["From beyond the door,\nthe distant voice of the student\ncertainly reached the father.\nYet he held the cup at his lips,","and said nothing."],"text_en":"From beyond the door,\nthe distant voice of the student\ncertainly reached the father.\nYet he held the cup at his lips,\nand said nothing."},{"no":8,"img":"assets/images/chapter_06/IMG-064.webp","pages":["座牢に残された娘の胸の奥には、\nいまだかつてない低き音が、\nひとつ鳴っていたのであった。"],"text":"座牢に残された娘の胸の奥には、\nいまだかつてない低き音が、\nひとつ鳴っていたのであった。","pages_en":["Within the Cell, in the girl's chest,\na low tone she had never known before\nrang out, distinct."],"text_en":"Within the Cell, in the girl's chest,\na low tone she had never known before\nrang out, distinct."}]},{"title":"第八章 ─ 共謀の夜","folder":"chapter_07","taps":[{"no":1,"img":"assets/images/chapter_07/IMG-065.webp","pages":["月の昏き夜が、ついに来た。\n屋敷の上空は厚き雲に覆われ、\n星の影すら見えない。","書生の言葉どおり、\n屋敷の犬は薬の効いた餌を腹に収め、\n犬小屋の中で深く眠っている。"],"text":"月の昏き夜が、ついに来た。\n屋敷の上空は厚き雲に覆われ、\n星の影すら見えない。\n書生の言葉どおり、\n屋敷の犬は薬の効いた餌を腹に収め、\n犬小屋の中で深く眠っている。","pages_en":["At last, the moonless night came.\nThe sky above the manor\nlay under thick cloud;\nnot even starlight showed.","As the student had promised,\nthe manor's watchdog had taken\nfood laced with drug,\nand slept deeply in its kennel."],"text_en":"At last, the moonless night came.\nThe sky above the manor\nlay under thick cloud;\nnot even starlight showed.\nAs the student had promised,\nthe manor's watchdog had taken\nfood laced with drug,\nand slept deeply in its kennel."},{"no":2,"img":"assets/images/chapter_07/IMG-066.webp","pages":["座牢の錠は、書生の手で予め解かれていた。\n格子戸の蝶番にも、\nひそかに油が差してある。"],"text":"座牢の錠は、書生の手で予め解かれていた。\n格子戸の蝶番にも、\nひそかに油が差してある。","pages_en":["The lock of the Cell,\nsecretly undone by the student's hand,\nyielded easily.\nOn the door's hinges, oil had been set."],"text_en":"The lock of the Cell,\nsecretly undone by the student's hand,\nyielded easily.\nOn the door's hinges, oil had been set."},{"no":3,"img":"assets/images/chapter_07/IMG-067.webp","pages":["娘は紫紺の羽織を手に取ると、\n廊下の闇へと身を滑らせる。\n書生は廊下の角で、\n灯を持たずに娘を待っていた。"],"text":"娘は紫紺の羽織を手に取ると、\n廊下の闇へと身を滑らせる。\n書生は廊下の角で、\n灯を持たずに娘を待っていた。","pages_en":["The girl took up her deep-violet haori\nand slid into the corridor's darkness.\nThe student waited at the corner\nwithout a lantern."],"text_en":"The girl took up her deep-violet haori\nand slid into the corridor's darkness.\nThe student waited at the corner\nwithout a lantern."},{"no":4,"img":"assets/images/chapter_00_intro/IMG-012.webp","pages":["二人は庭の砂利を抜け、\n籬の隙の方角へと向かう。庭の砂利は、\n二人の足元をやわらかく沈ませた。\nだが、その時――、","娘の裾に、ひとつの影がぴたりと\n寄り添ってきた。\n屋敷の老猫であった。\nなぜか、娘の後をついて来ている。","二人と一匹で籬の隙を抜けようとした、\n刹那──。\n霧の向こうから、提灯の灯がふたつ、\nぼうと浮かんで近づいてきた。"],"text":"二人は庭の砂利を抜け、\n籬の隙の方角へと向かう。庭の砂利は、\n二人の足元をやわらかく沈ませた。\nだが、その時――、\n娘の裾に、ひとつの影がぴたりと\n寄り添ってきた。\n屋敷の老猫であった。\nなぜか、娘の後をついて来ている。\n二人と一匹で籬の隙を抜けようとした、\n刹那──。\n霧の向こうから、提灯の灯がふたつ、\nぼうと浮かんで近づいてきた。","pages_en":["The two of them passed the garden's gravel\ntoward the gap in the fence.\nThe gravel gave softly beneath their feet.\nBut in that moment ─","a shadow drew close\nto the girl's hem.\nIt was the old cat of the manor.\nFor reasons unknown, it followed her.","The two of them, and one cat,\nreached the gap in the fence,\nand in that very instant ─\ntwo lantern lights loomed through the mist."],"text_en":"The two of them passed the garden's gravel\ntoward the gap in the fence.\nThe gravel gave softly beneath their feet.\nBut in that moment ─\na shadow drew close\nto the girl's hem.\nIt was the old cat of the manor.\nFor reasons unknown, it followed her.\nThe two of them, and one cat,\nreached the gap in the fence,\nand in that very instant ─\ntwo lantern lights loomed through the mist."},{"no":5,"img":"assets/images/chapter_07/IMG-068.webp","pages":["提灯を掲げているのは、番頭であった。\n番頭の後ろには、父の姿があり、\n肩を強張らせたまま立っていた。","父の頬には、酒の余りの赤みが\nうっすらと残っていた。\n「娘様、どうかこちらへ」\n野太い番頭の声が駆け抜け、","筋骨隆々の手が、\n娘の腕に届くより一瞬早く、\n書生の手が、娘の腕を強く掴んだ。"],"text":"提灯を掲げているのは、番頭であった。\n番頭の後ろには、父の姿があり、\n肩を強張らせたまま立っていた。\n父の頬には、酒の余りの赤みが\nうっすらと残っていた。\n「娘様、どうかこちらへ」\n野太い番頭の声が駆け抜け、\n筋骨隆々の手が、\n娘の腕に届くより一瞬早く、\n書生の手が、娘の腕を強く掴んだ。","pages_en":["The lantern was raised by the head clerk.\nBehind him stood the father,\nshoulders tightened,\nunmoving in the mist.","A faint flush of sake\nstill lingered on the father's cheeks.\n\"Young mistress, come this way,\"\nthe clerk called out, thick and low.","Yet a heartbeat before that hand\ncould reach the girl's arm,\nthe student's hand seized\nher wrist and held her fast."],"text_en":"The lantern was raised by the head clerk.\nBehind him stood the father,\nshoulders tightened,\nunmoving in the mist.\nA faint flush of sake\nstill lingered on the father's cheeks.\n\"Young mistress, come this way,\"\nthe clerk called out, thick and low.\nYet a heartbeat before that hand\ncould reach the girl's arm,\nthe student's hand seized\nher wrist and held her fast."},{"no":6,"img":"assets/images/chapter_07/IMG-069.webp","pages":["「行きましょう」──。\n 書生が、震えながら言葉を絞り出すが、\n「お祖父様にお仕えする身が何の真似じゃ」\n 父の鋭い声が、書生の動きをとめた。","番頭の手は書生の指を\nひと振りで娘の腕から解いた。\n続けて足元にまとわりつく老猫を、\n無造作に蹴り上げた。","猫は短く鳴き、霧の中へと転がっていく。\n二人は番頭の手によって、\n再び屋敷の中へと連れ戻されたのであった。"],"text":"「行きましょう」──。\n 書生が、震えながら言葉を絞り出すが、\n「お祖父様にお仕えする身が何の真似じゃ」\n 父の鋭い声が、書生の動きをとめた。\n番頭の手は書生の指を\nひと振りで娘の腕から解いた。\n続けて足元にまとわりつく老猫を、\n無造作に蹴り上げた。\n猫は短く鳴き、霧の中へと転がっていく。\n二人は番頭の手によって、\n再び屋敷の中へと連れ戻されたのであった。","pages_en":["\"Let us go,\" said the student,\nsqueezing the words through his trembling.\n\"You who serve my father ─\nwhat play is this?\"","The father's sharp voice\nfroze the student where he stood.\nThe clerk's hand tore the student's fingers\nfrom the girl in a single stroke.","Then he kicked, without a glance,\nthe old cat clinging to his feet.\nThe cat cried out once, briefly,\nand tumbled into the mist.","The two of them\nwere led back into the manor\nby the head clerk's hand."],"text_en":"\"Let us go,\" said the student,\nsqueezing the words through his trembling.\n\"You who serve my father ─\nwhat play is this?\"\nThe father's sharp voice\nfroze the student where he stood.\nThe clerk's hand tore the student's fingers\nfrom the girl in a single stroke.\nThen he kicked, without a glance,\nthe old cat clinging to his feet.\nThe cat cried out once, briefly,\nand tumbled into the mist.\nThe two of them\nwere led back into the manor\nby the head clerk's hand."},{"no":7,"img":"assets/images/chapter_00_intro/IMG-012.webp","pages":["霧の中には、ただ――、\n老猫の最後の鳴き声の余韻だけが、\n長く長く尾を引いていたのであった。"],"text":"霧の中には、ただ――、\n老猫の最後の鳴き声の余韻だけが、\n長く長く尾を引いていたのであった。","pages_en":["In the mist,\nonly the echo of the old cat's last cry\ntrailed on and on,\nlong into the night."],"text_en":"In the mist,\nonly the echo of the old cat's last cry\ntrailed on and on,\nlong into the night."}]},{"title":"第九章 ─ 庭の骸と祭壇の影","folder":"chapter_08","taps":[{"no":1,"img":"assets/images/chapter_08/IMG-070.webp","pages":["翌朝の早く、屋敷の裏庭で、\n番頭がひとつの布包みを抱えていた。"],"text":"翌朝の早く、屋敷の裏庭で、\n番頭がひとつの布包みを抱えていた。","pages_en":["Early the next morning,\nin the manor's back garden,\nthe head clerk carried a wrapped bundle."],"text_en":"Early the next morning,\nin the manor's back garden,\nthe head clerk carried a wrapped bundle."},{"no":2,"img":"assets/images/chapter_08/IMG-070.webp","pages":["布包みの中身は、昨夜の老猫の骸である。\n番頭はそれを屋敷の裏の竹藪の方角へと\n運んでゆく。"],"text":"布包みの中身は、昨夜の老猫の骸である。\n番頭はそれを屋敷の裏の竹藪の方角へと\n運んでゆく。","pages_en":["Within the wrapping\nlay the body of last night's cat.\nHe carried it toward the bamboo grove\nbehind the manor."],"text_en":"Within the wrapping\nlay the body of last night's cat.\nHe carried it toward the bamboo grove\nbehind the manor."},{"no":3,"img":"assets/images/chapter_08/IMG-071.webp","pages":["竹藪の手前では、祭祀役の兄が、\n燈明の灯を片手に静かに立っていた。\n番頭が骸を竹藪の根元に置くのを、\n兄はただ無言で見つめる。","番頭が竹藪を去った後、兄の視線は、\n骸の向こうにある特別な場所──、","祭壇をいつまでも見つめていた。\nやがて兄の視線は、骸でも祭壇でもなく、\n兄自身の足元へと、静かに落ちてゆく。"],"text":"竹藪の手前では、祭祀役の兄が、\n燈明の灯を片手に静かに立っていた。\n番頭が骸を竹藪の根元に置くのを、\n兄はただ無言で見つめる。\n番頭が竹藪を去った後、兄の視線は、\n骸の向こうにある特別な場所──、\n祭壇をいつまでも見つめていた。\nやがて兄の視線は、骸でも祭壇でもなく、\n兄自身の足元へと、静かに落ちてゆく。","pages_en":["Before the grove,\nthe elder brother, tender of the shrine,\nstood quietly, a votive lamp in hand.\nHe watched, in silence,","as the clerk set the small body\nat the roots of the bamboo.\nOnce the clerk had gone,\nthe brother's gaze passed beyond the body ─","and settled long upon the altar.\nAt last, his eyes fell\nneither on the body nor the altar,\nbut quietly, upon his own feet."],"text_en":"Before the grove,\nthe elder brother, tender of the shrine,\nstood quietly, a votive lamp in hand.\nHe watched, in silence,\nas the clerk set the small body\nat the roots of the bamboo.\nOnce the clerk had gone,\nthe brother's gaze passed beyond the body ─\nand settled long upon the altar.\nAt last, his eyes fell\nneither on the body nor the altar,\nbut quietly, upon his own feet."},{"no":4,"img":"assets/images/chapter_08/IMG-072.webp","pages":["同じ朝、屋敷の中ほどの台所では、\n母が膳の支度を終えていた。\n膳の上の塩むすびは、\n心なしか、形が歪んでいる。"],"text":"同じ朝、屋敷の中ほどの台所では、\n母が膳の支度を終えていた。\n膳の上の塩むすびは、\n心なしか、形が歪んでいる。","pages_en":["That same morning,\nin the kitchen at the center of the manor,\nthe mother had finished the tray.\nThe rice ball's shape, somehow, was crooked."],"text_en":"That same morning,\nin the kitchen at the center of the manor,\nthe mother had finished the tray.\nThe rice ball's shape, somehow, was crooked."},{"no":5,"img":"assets/images/chapter_08/IMG-073.webp","pages":["母は膳を手に、廊下を歩く。\n座牢の前まで来ると、格子戸の脇の\n小窓を開き、膳を中へと差し入れた。\n母は今朝、ひとつも口を利かなかった。"],"text":"母は膳を手に、廊下を歩く。\n座牢の前まで来ると、格子戸の脇の\n小窓を開き、膳を中へと差し入れた。\n母は今朝、ひとつも口を利かなかった。","pages_en":["Tray in hand, she walked the hall.\nAt the Cell, she opened the small hatch\nand pushed the tray through.\nThat morning, she did not speak once."],"text_en":"Tray in hand, she walked the hall.\nAt the Cell, she opened the small hatch\nand pushed the tray through.\nThat morning, she did not speak once."},{"no":6,"img":"assets/images/chapter_08/IMG-074.webp","pages":["娘の指先がそっと、格子の隙を通して、\n母の指に触れる。\nけれども母は静かに袂を引き、\n廊下を戻ってゆく。","母の歩みは、他の朝とは、\n何かが違うように見えた。"],"text":"娘の指先がそっと、格子の隙を通して、\n母の指に触れる。\nけれども母は静かに袂を引き、\n廊下を戻ってゆく。\n母の歩みは、他の朝とは、\n何かが違うように見えた。","pages_en":["The girl's fingertips\nsoftly passed through the lattice,\nand touched her mother's hand.\nBut the mother quietly drew her sleeve back,","and returned down the hall.\nHer gait, this morning,\ncarried something different\nfrom all the others."],"text_en":"The girl's fingertips\nsoftly passed through the lattice,\nand touched her mother's hand.\nBut the mother quietly drew her sleeve back,\nand returned down the hall.\nHer gait, this morning,\ncarried something different\nfrom all the others."},{"no":7,"img":"assets/images/chapter_08/IMG-075.webp","pages":["同じ刻、屋敷の納屋の脇では、\n父が酒杯を傾けていた。\n盃の縁を口に当てる手が、\nほんのわずかに震えている。"],"text":"同じ刻、屋敷の納屋の脇では、\n父が酒杯を傾けていた。\n盃の縁を口に当てる手が、\nほんのわずかに震えている。","pages_en":["At that hour, beside the storehouse,\nthe father was tilting his cup.\nThe hand that pressed the rim to his lips\ntrembled the barest amount."],"text_en":"At that hour, beside the storehouse,\nthe father was tilting his cup.\nThe hand that pressed the rim to his lips\ntrembled the barest amount."},{"no":8,"img":"assets/images/chapter_08/IMG-076.webp","pages":["膳の塩むすびを見つめる娘の指には、\n昨夜書生が掴んだ手の感触が、\n消えずに残っていた……。"],"text":"膳の塩むすびを見つめる娘の指には、\n昨夜書生が掴んだ手の感触が、\n消えずに残っていた……。","pages_en":["Upon the rice ball of the tray,\nthe girl's fingers still bore\nthe touch of the student's grip\nfrom the night before…"],"text_en":"Upon the rice ball of the tray,\nthe girl's fingers still bore\nthe touch of the student's grip\nfrom the night before…"}]},{"title":"第十章 ─ 座敷の怒号と蔵の影","folder":"chapter_09","taps":[{"no":1,"img":"assets/images/chapter_09/IMG-077.webp","pages":["その日の昼下がり、屋敷の南面の座敷から、\n父の怒号が突如として響き渡った。\n座敷の中央には、書生が畳に手をついて\n控えている。","父はその書生を前に、\n煙管を畳に強く打ちつけた。\n「お前様は、何のために\n此処に居るのじゃ！」","父の声には、家の主としての怒気のほかに、\n何かをかろうじて押さえつけているような\n奇妙な揺らぎが、混じっていた。"],"text":"その日の昼下がり、屋敷の南面の座敷から、\n父の怒号が突如として響き渡った。\n座敷の中央には、書生が畳に手をついて\n控えている。\n父はその書生を前に、\n煙管を畳に強く打ちつけた。\n「お前様は、何のために\n此処に居るのじゃ！」\n父の声には、家の主としての怒気のほかに、\n何かをかろうじて押さえつけているような\n奇妙な揺らぎが、混じっていた。","pages_en":["That day, in the afternoon,\nfrom the south parlor of the manor,\nthe father's shouting suddenly rang out.\nBefore him, the student knelt low.","The father, before the student,\nstruck his pipe hard against the tatami.\n\"What purpose brings you\ninto this house?\"","In the father's voice,\nbeyond a master's anger,\nlay a strange wavering ─\nas though something else was held back."],"text_en":"That day, in the afternoon,\nfrom the south parlor of the manor,\nthe father's shouting suddenly rang out.\nBefore him, the student knelt low.\nThe father, before the student,\nstruck his pipe hard against the tatami.\n\"What purpose brings you\ninto this house?\"\nIn the father's voice,\nbeyond a master's anger,\nlay a strange wavering ─\nas though something else was held back."},{"no":2,"img":"assets/images/chapter_09/IMG-078.webp","pages":["そのとき、座敷の襖が静かに開き、\n叔母が裾を引きながら入ってきた。"],"text":"そのとき、座敷の襖が静かに開き、\n叔母が裾を引きながら入ってきた。","pages_en":["At that moment the door slid open,\nand the aunt entered,\ntrailing the hem of her robe."],"text_en":"At that moment the door slid open,\nand the aunt entered,\ntrailing the hem of her robe."},{"no":3,"img":"assets/images/chapter_09/IMG-079.webp","pages":["「弟様、お目を瞑り下さりませ。\nこの者は、私の縁で雇うた者にござります」\n叔母の声は、父の怒号とは打って変わって、\n冷たく澄んでいた。","父は顔をしかめた後、長き息を吐いた。\nそれから、煙管を畳の上に叩きつけると、\n奥の襖の方へと歩み去った。"],"text":"「弟様、お目を瞑り下さりませ。\nこの者は、私の縁で雇うた者にござります」\n叔母の声は、父の怒号とは打って変わって、\n冷たく澄んでいた。\n父は顔をしかめた後、長き息を吐いた。\nそれから、煙管を畳の上に叩きつけると、\n奥の襖の方へと歩み去った。","pages_en":["\"Younger brother, avert your eyes.\nThis one was taken into service\nthrough my connections,\" said the aunt.","Her voice, cool and clear,\nstood apart from the father's rage.\nThe father grimaced, drew a long breath,\nthen threw his pipe down","and departed toward the inner door."],"text_en":"\"Younger brother, avert your eyes.\nThis one was taken into service\nthrough my connections,\" said the aunt.\nHer voice, cool and clear,\nstood apart from the father's rage.\nThe father grimaced, drew a long breath,\nthen threw his pipe down\nand departed toward the inner door."},{"no":4,"img":"assets/images/chapter_09/IMG-080.webp","pages":["夜も更けた頃――、\n屋敷の蔵に、ひとつの灯がともっていた。\n蔵の中では、書生が古文書の頁を膝に開き、\n灯の下で文字を写し取っていた。","書生の傍らには、叔父の影が控えている。\n叔父は紙を覗き込み、低く一言を漏らした。"],"text":"夜も更けた頃――、\n屋敷の蔵に、ひとつの灯がともっていた。\n蔵の中では、書生が古文書の頁を膝に開き、\n灯の下で文字を写し取っていた。\n書生の傍らには、叔父の影が控えている。\n叔父は紙を覗き込み、低く一言を漏らした。","pages_en":["Late that night,\nin the storehouse of the manor,\na single lamp burned.\nWithin, the student had opened","an old text upon his knees\nand was transcribing its characters\nbeneath the lamp.\nBeside him stood the uncle's shadow."],"text_en":"Late that night,\nin the storehouse of the manor,\na single lamp burned.\nWithin, the student had opened\nan old text upon his knees\nand was transcribing its characters\nbeneath the lamp.\nBeside him stood the uncle's shadow."},{"no":5,"img":"assets/images/chapter_09/IMG-081.webp","pages":["「何の文字じゃ」\n 叔父の問いに、書生は\n文字の上に指を置き、静かに返した。\n「これは……神の名でしょうか」","「分からぬ……。\nだが、何ぞの呪術の符牒であるな」\nそう呟く叔父の眼は妖しく輝いていた。"],"text":"「何の文字じゃ」\n 叔父の問いに、書生は\n文字の上に指を置き、静かに返した。\n「これは……神の名でしょうか」\n「分からぬ……。\nだが、何ぞの呪術の符牒であるな」\nそう呟く叔父の眼は妖しく輝いていた。","pages_en":["The uncle leaned close over the paper\nand murmured, low:\n\"What character is this?\"\nThe student set his finger on the mark","and answered quietly:\n\"Perhaps… the name of a god.\"\n\"I do not know,\" said the uncle,\n\"but it is a cipher of some spellcraft.\"","His eyes shone with an eerie light."],"text_en":"The uncle leaned close over the paper\nand murmured, low:\n\"What character is this?\"\nThe student set his finger on the mark\nand answered quietly:\n\"Perhaps… the name of a god.\"\n\"I do not know,\" said the uncle,\n\"but it is a cipher of some spellcraft.\"\nHis eyes shone with an eerie light."},{"no":6,"img":"assets/images/chapter_10/IMG-166.webp","pages":["同じ刻、蔵の前には、別の影が立っていた。\n叔母である――。叔母は、\n書生が蔵を去って自室へ戻る頃合いを、\n身じろぎもせずに待ち続けていた。"],"text":"同じ刻、蔵の前には、別の影が立っていた。\n叔母である――。叔母は、\n書生が蔵を去って自室へ戻る頃合いを、\n身じろぎもせずに待ち続けていた。","pages_en":["At that same hour,\nbefore the storehouse\nanother figure stood ─ the aunt.\nShe waited without stirring","for the time when the student\nwould leave and return to his room."],"text_en":"At that same hour,\nbefore the storehouse\nanother figure stood ─ the aunt.\nShe waited without stirring\nfor the time when the student\nwould leave and return to his room."},{"no":7,"img":"assets/images/chapter_10/IMG-166.webp","pages":["座牢の格子越しには、蔵の灯と、\n叔母の影とが、二つともわずかに望めた。"],"text":"座牢の格子越しには、蔵の灯と、\n叔母の影とが、二つともわずかに望めた。","pages_en":["Through the lattice of the Cell,\nboth the storehouse's lamp\nand the aunt's shadow\ncould just be seen."],"text_en":"Through the lattice of the Cell,\nboth the storehouse's lamp\nand the aunt's shadow\ncould just be seen."},{"no":8,"img":"assets/images/chapter_09/IMG-082.webp","pages":["娘は、その二つを、しばらく交互に\n見つめていたのであった。"],"text":"娘は、その二つを、しばらく交互に\n見つめていたのであった。","pages_en":["The girl watched both, in turn,\nfor a long time."],"text_en":"The girl watched both, in turn,\nfor a long time."}]},{"title":"第十一章 ─ 燈下の影","folder":"chapter_10","taps":[{"no":1,"img":"assets/images/chapter_10/IMG-083.webp","pages":["数日が過ぎた朝、屋敷の書斎では、\n祖父と父が並んで座していた。\n祖父は煙管を吹かしながら、\nゆっくりと父を見る。","「……喜べ。そろそろ、お前にも、\n大きな仕事をさせてやろう」\n祖父は煙を細く吐き、言葉を付け加えた。\n「まだまだ半人前じゃが、気張るがいい」","父は畳に手をついたまま応えなかった。\n父の指の節が、わずかに白く浮き上がる。"],"text":"数日が過ぎた朝、屋敷の書斎では、\n祖父と父が並んで座していた。\n祖父は煙管を吹かしながら、\nゆっくりと父を見る。\n「……喜べ。そろそろ、お前にも、\n大きな仕事をさせてやろう」\n祖父は煙を細く吐き、言葉を付け加えた。\n「まだまだ半人前じゃが、気張るがいい」\n父は畳に手をついたまま応えなかった。\n父の指の節が、わずかに白く浮き上がる。","pages_en":["A few days later, in the morning,\nGrandfather and the father\nsat side by side in the study.\nGrandfather drew slowly on his pipe","and looked at his son.\n\"…Rejoice. Soon I shall entrust you\nwith greater work.\"\nHe blew a thin ribbon of smoke.","\"You are still less than half a man,\nbut labor well.\"\nThe father made no reply,\nhands pressed to the tatami.","The knuckles of his fingers\nrose faintly pale."],"text_en":"A few days later, in the morning,\nGrandfather and the father\nsat side by side in the study.\nGrandfather drew slowly on his pipe\nand looked at his son.\n\"…Rejoice. Soon I shall entrust you\nwith greater work.\"\nHe blew a thin ribbon of smoke.\n\"You are still less than half a man,\nbut labor well.\"\nThe father made no reply,\nhands pressed to the tatami.\nThe knuckles of his fingers\nrose faintly pale."},{"no":2,"img":"assets/images/chapter_10/IMG-084.webp","pages":["廊下の蔭では、母が壁に身を寄せ、\n二人の声をじっと立ち聞きしていた。"],"text":"廊下の蔭では、母が壁に身を寄せ、\n二人の声をじっと立ち聞きしていた。","pages_en":["In the shadow of the corridor,\nthe mother pressed herself to the wall,\nlistening to both voices\nwithout a sound."],"text_en":"In the shadow of the corridor,\nthe mother pressed herself to the wall,\nlistening to both voices\nwithout a sound."},{"no":3,"img":"assets/images/chapter_10/IMG-085.webp","pages":["「半人前とは……あまりにむごい」\n母の唇はその独り言を、\n誰にも届かぬ声で零した。"],"text":"「半人前とは……あまりにむごい」\n母の唇はその独り言を、\n誰にも届かぬ声で零した。","pages_en":["\"Less than half a man ─\nsuch cruelty…\"\nHer murmur, to no ear,\nescaped her lips."],"text_en":"\"Less than half a man ─\nsuch cruelty…\"\nHer murmur, to no ear,\nescaped her lips."},{"no":4,"img":"assets/images/chapter_10/IMG-086.webp","pages":["母は袂で目を拭うと、\n納戸の方へと去ってゆく。"],"text":"母は袂で目を拭うと、\n納戸の方へと去ってゆく。","pages_en":["Wiping her eyes with her sleeve,\nshe departed toward the storeroom."],"text_en":"Wiping her eyes with her sleeve,\nshe departed toward the storeroom."},{"no":5,"img":"assets/images/chapter_10/IMG-087.webp","pages":["その夜、屋敷の縁側を、父がひとり、\n酒杯を片手に渡っていた。\n痩せた背は、夜風にやや前のめりであった。\n父の歩みは奇妙なほどゆっくりとしている。","それは祖父への怯えとも、\n不甲斐ない自分への怒りとも、\n酒の重みとも、いずれにも見えた。"],"text":"その夜、屋敷の縁側を、父がひとり、\n酒杯を片手に渡っていた。\n痩せた背は、夜風にやや前のめりであった。\n父の歩みは奇妙なほどゆっくりとしている。\nそれは祖父への怯えとも、\n不甲斐ない自分への怒りとも、\n酒の重みとも、いずれにも見えた。","pages_en":["That night, upon the veranda of the manor,\nthe father walked alone,\na sake cup in one hand.\nHis thin back leaned slightly forward","against the night wind.\nHis pace was strangely slow.\nWhether from fear of Grandfather,\nfrom rage at his own weakness,","or from the weight of drink ─\nit seemed all three."],"text_en":"That night, upon the veranda of the manor,\nthe father walked alone,\na sake cup in one hand.\nHis thin back leaned slightly forward\nagainst the night wind.\nHis pace was strangely slow.\nWhether from fear of Grandfather,\nfrom rage at his own weakness,\nor from the weight of drink ─\nit seemed all three."},{"no":6,"img":"assets/images/chapter_10/IMG-088.webp","pages":["夜更け、母は寝所の襖を音もなく開け、\n父のいる縁側に姿を見せた。\nその手には酒杯があった。"],"text":"夜更け、母は寝所の襖を音もなく開け、\n父のいる縁側に姿を見せた。\nその手には酒杯があった。","pages_en":["Late in the night,\nthe mother slid open the door\nwithout a sound and appeared\non the veranda where he sat, cup in hand."],"text_en":"Late in the night,\nthe mother slid open the door\nwithout a sound and appeared\non the veranda where he sat, cup in hand."},{"no":7,"img":"assets/images/chapter_10/IMG-089.webp","pages":["二人は縁側に並んで座り、\n月のない夜空をしばらく見上げた。\n言葉は、ひとつも交わされなかった。"],"text":"二人は縁側に並んで座り、\n月のない夜空をしばらく見上げた。\n言葉は、ひとつも交わされなかった。","pages_en":["The two sat side by side\nand looked up at the moonless sky\nfor a long while.\nNot a single word was spoken."],"text_en":"The two sat side by side\nand looked up at the moonless sky\nfor a long while.\nNot a single word was spoken."},{"no":8,"img":"assets/images/chapter_10/IMG-090.webp","pages":["座牢の高窓の隙からは、\nその縁側の灯が、わずかに見える。\n父と母の影は、月のない夜空の下で、\nいつまでも並んだままであった。"],"text":"座牢の高窓の隙からは、\nその縁側の灯が、わずかに見える。\n父と母の影は、月のない夜空の下で、\nいつまでも並んだままであった。","pages_en":["Through the crack of the Cell's high window,\nthe faint glow of the veranda's lamp\ncould still be seen.\nThe two shadows, husband and wife,","remained side by side\nbeneath the moonless sky,\nfar into the night."],"text_en":"Through the crack of the Cell's high window,\nthe faint glow of the veranda's lamp\ncould still be seen.\nThe two shadows, husband and wife,\nremained side by side\nbeneath the moonless sky,\nfar into the night."}]},{"title":"第十二章 ─ 蔵の文字と兄の油","folder":"chapter_11","taps":[{"no":1,"img":"assets/images/chapter_11/IMG-091.webp","pages":["また別の夜、屋敷の蔵に、\nひとつの灯が小さく揺れていた。\n蔵の中では、書生が古文書を膝に広げ、\n灯の下で文字を、紙に写し取っている。","傍らには、叔父の影があり、\n叔父は覗き込むように身を寄せていた。\n写し取られている文字は、「籠」の「目」\nを編むに似た、奇しき形をしている。","「これと同じ形を、この屋敷の何処かで、\n見た覚えがござります」\n書生は和紙の文字を指で撫でながら、\nぼそりと呟いた。","「いずこの形と申すか？」\n叔父は文字を覗き込みつつ、\n声を絞り出す。"],"text":"また別の夜、屋敷の蔵に、\nひとつの灯が小さく揺れていた。\n蔵の中では、書生が古文書を膝に広げ、\n灯の下で文字を、紙に写し取っている。\n傍らには、叔父の影があり、\n叔父は覗き込むように身を寄せていた。\n写し取られている文字は、「籠」の「目」\nを編むに似た、奇しき形をしている。\n「これと同じ形を、この屋敷の何処かで、\n見た覚えがござります」\n書生は和紙の文字を指で撫でながら、\nぼそりと呟いた。\n「いずこの形と申すか？」\n叔父は文字を覗き込みつつ、\n声を絞り出す。","pages_en":["Another night, in the manor's storehouse,\na single lamp swayed dimly.\nThe student had opened an old text\nupon his knees,","and beneath the lamp\nwas copying its characters onto paper.\nBeside him stood the uncle's shadow,\nleaning in to peer close.","The character being written\nresembled a plaited kagome basket ─\na strange form.","\"I recall having seen this form\nsomewhere else in this manor,\"\nsaid the student, tracing the mark\nwith his finger.","\"Where would that be?\"\nthe uncle whispered,\npeering into the paper."],"text_en":"Another night, in the manor's storehouse,\na single lamp swayed dimly.\nThe student had opened an old text\nupon his knees,\nand beneath the lamp\nwas copying its characters onto paper.\nBeside him stood the uncle's shadow,\nleaning in to peer close.\nThe character being written\nresembled a plaited kagome basket ─\na strange form.\n\"I recall having seen this form\nsomewhere else in this manor,\"\nsaid the student, tracing the mark\nwith his finger.\n\"Where would that be?\"\nthe uncle whispered,\npeering into the paper."},{"no":2,"img":"assets/images/chapter_11/IMG-092.webp","pages":["「座牢の格子。あの籠目の文様に、\nこの形があったのでござります」\n蔵の入口に、もうひとつの影が\n静かに加わった。兄である。","手には、油の壺をひとつ携えていた。"],"text":"「座牢の格子。あの籠目の文様に、\nこの形があったのでござります」\n蔵の入口に、もうひとつの影が\n静かに加わった。兄である。\n手には、油の壺をひとつ携えていた。","pages_en":["\"The lattice of the Cell.\nThat kagome pattern ─\nthis form was there.\"\nAt the storehouse door, another shadow","quietly joined them.\nIt was the elder brother.\nIn his hand,\nhe carried a jar of oil."],"text_en":"\"The lattice of the Cell.\nThat kagome pattern ─\nthis form was there.\"\nAt the storehouse door, another shadow\nquietly joined them.\nIt was the elder brother.\nIn his hand,\nhe carried a jar of oil."},{"no":3,"img":"assets/images/chapter_11/IMG-093.webp","pages":["兄は書生にも叔父にも目を合わせず、\n無言で油壺を蔵の隅に置くと、\nまた静かに去ってゆく。"],"text":"兄は書生にも叔父にも目を合わせず、\n無言で油壺を蔵の隅に置くと、\nまた静かに去ってゆく。","pages_en":["Meeting the eyes of neither,\nthe brother set the jar in the corner\nof the storehouse,\nand quietly went away."],"text_en":"Meeting the eyes of neither,\nthe brother set the jar in the corner\nof the storehouse,\nand quietly went away."},{"no":4,"img":"assets/images/chapter_11/IMG-094.webp","pages":["祭壇の燈明を絶やさぬ役目を、\n兄は夜ごと、屋敷の方々の灯火についても、\nひとりで担っていたのである。"],"text":"祭壇の燈明を絶やさぬ役目を、\n兄は夜ごと、屋敷の方々の灯火についても、\nひとりで担っていたのである。","pages_en":["The task of keeping the altar's flame,\nand every lamp of the manor,\nfell to the elder brother alone,\nnight after night."],"text_en":"The task of keeping the altar's flame,\nand every lamp of the manor,\nfell to the elder brother alone,\nnight after night."},{"no":5,"img":"assets/images/chapter_11/IMG-095.webp","pages":["兄の姿が蔵の闇に消えた後、\n叔父はゆっくりと立ち上がり、\n蔵の入口に立った。"],"text":"兄の姿が蔵の闇に消えた後、\n叔父はゆっくりと立ち上がり、\n蔵の入口に立った。","pages_en":["When the brother vanished into darkness,\nthe uncle slowly rose\nand stood at the storehouse door."],"text_en":"When the brother vanished into darkness,\nthe uncle slowly rose\nand stood at the storehouse door."},{"no":6,"img":"assets/images/chapter_11/IMG-096.webp","pages":["叔父はそのまま、廊下を渡って、\n座牢の前で足を止める。\n何ひとつ言葉を発さぬまま、長く、\nその場を動かずにいる。"],"text":"叔父はそのまま、廊下を渡って、\n座牢の前で足を止める。\n何ひとつ言葉を発さぬまま、長く、\nその場を動かずにいる。","pages_en":["He crossed the corridor and stopped\nbefore the Cell.\nWithout uttering a single word,\nhe stood there long, unmoving."],"text_en":"He crossed the corridor and stopped\nbefore the Cell.\nWithout uttering a single word,\nhe stood there long, unmoving."},{"no":7,"img":"assets/images/chapter_11/IMG-097.webp","pages":["やがてその影は、\nゆっくりと廊下の闇の奥へ解けて\n行ったのであった。"],"text":"やがてその影は、\nゆっくりと廊下の闇の奥へ解けて\n行ったのであった。","pages_en":["At length, his shadow\ndissolved slowly\ninto the depths of the hall's darkness."],"text_en":"At length, his shadow\ndissolved slowly\ninto the depths of the hall's darkness."}]},{"title":"第十三章 ─ 手形の符号","folder":"chapter_12","taps":[{"no":1,"img":"assets/images/chapter_12/IMG-098.webp","pages":["翌朝、屋敷の座牢の柱に、\nまた朱の手形がひとつ、増えていた。"],"text":"翌朝、屋敷の座牢の柱に、\nまた朱の手形がひとつ、増えていた。","pages_en":["The next morning, on a pillar of the Cell,\nyet another vermilion print\nhad been added."],"text_en":"The next morning, on a pillar of the Cell,\nyet another vermilion print\nhad been added."},{"no":2,"img":"assets/images/chapter_12/IMG-099.webp","pages":["いつの間にか、この朱の印は、\n屋敷の至るところに\n静かに増え続けている。"],"text":"いつの間にか、この朱の印は、\n屋敷の至るところに\n静かに増え続けている。","pages_en":["When had it begun?\nThis crimson mark\nwas quietly multiplying\nthroughout the manor."],"text_en":"When had it begun?\nThis crimson mark\nwas quietly multiplying\nthroughout the manor."},{"no":3,"img":"assets/images/chapter_12/IMG-100.webp","pages":["廊下の柱、襖の縁、欄間の桟──。\nあちこちに点々と朱が滲んでいた。\n廊下を通りがかった妹が、その印に気づき、\n母の袂に駆け寄って縋りつく。","「お母さん、あれ、なあに？」\n「あれ、こわい」\n妹の小さな手が、母の袂の中で震えた。\n母は妹の手を引き、ふと目を伏せる。","「気にせんでも、すぐ消えるものじゃ」\n母はそれだけを告げると、\n妹の手を引いて、納戸の方へと姿を消した。"],"text":"廊下の柱、襖の縁、欄間の桟──。\nあちこちに点々と朱が滲んでいた。\n廊下を通りがかった妹が、その印に気づき、\n母の袂に駆け寄って縋りつく。\n「お母さん、あれ、なあに？」\n「あれ、こわい」\n妹の小さな手が、母の袂の中で震えた。\n母は妹の手を引き、ふと目を伏せる。\n「気にせんでも、すぐ消えるものじゃ」\n母はそれだけを告げると、\n妹の手を引いて、納戸の方へと姿を消した。","pages_en":["Corridor pillars, the edges of doors,\nthe rails of the transom ─\ncrimson stained here and there.\nThe younger sister passed by,","saw them, and clung\nto her mother's sleeve.\n\"Mother, what is that?\nIt's scary.\"","The small hand trembled\ninside the mother's sleeve.\nThe mother took her daughter's hand\nand cast her eyes down.","\"Pay it no mind ─\nit shall soon vanish.\"\nSo saying, she led the child\ntoward the storeroom, and was gone."],"text_en":"Corridor pillars, the edges of doors,\nthe rails of the transom ─\ncrimson stained here and there.\nThe younger sister passed by,\nsaw them, and clung\nto her mother's sleeve.\n\"Mother, what is that?\nIt's scary.\"\nThe small hand trembled\ninside the mother's sleeve.\nThe mother took her daughter's hand\nand cast her eyes down.\n\"Pay it no mind ─\nit shall soon vanish.\"\nSo saying, she led the child\ntoward the storeroom, and was gone."},{"no":4,"img":"assets/images/chapter_12/IMG-101.webp","pages":["廊下の往来が遠ざかった後、\nその場には、娘がひとり残されていた。"],"text":"廊下の往来が遠ざかった後、\nその場には、娘がひとり残されていた。","pages_en":["After the footsteps departed,\nthe girl was left alone in the hall."],"text_en":"After the footsteps departed,\nthe girl was left alone in the hall."},{"no":5,"img":"assets/images/chapter_12/IMG-102.webp","pages":["娘は障子の手形を、しばし見つめる。\nそれから、おそるおそる、\n自分の掌をその朱に重ねてみた。","朱の手形と娘の掌の輪郭は、\n寸分の違いとて、見出されなかった。\n娘の指が震えながら、手形から\nゆっくりと離れてゆく。"],"text":"娘は障子の手形を、しばし見つめる。\nそれから、おそるおそる、\n自分の掌をその朱に重ねてみた。\n朱の手形と娘の掌の輪郭は、\n寸分の違いとて、見出されなかった。\n娘の指が震えながら、手形から\nゆっくりと離れてゆく。","pages_en":["She gazed for a while\nat the crimson print on the door.\nThen, with cautious care,\nshe laid her own palm against it.","Between the vermilion print\nand her own hand,\nthere was not a hair's difference.\nHer fingers trembled as they drew away."],"text_en":"She gazed for a while\nat the crimson print on the door.\nThen, with cautious care,\nshe laid her own palm against it.\nBetween the vermilion print\nand her own hand,\nthere was not a hair's difference.\nHer fingers trembled as they drew away."},{"no":6,"img":"assets/images/chapter_12/IMG-101.webp","pages":["指先には、知らぬ間にも、\n自分の鼓動がしかと伝わる。同時に、\n娘は自らの鼓動が手形にも伝わって\nいるのではないかと思ったのであった。"],"text":"指先には、知らぬ間にも、\n自分の鼓動がしかと伝わる。同時に、\n娘は自らの鼓動が手形にも伝わって\nいるのではないかと思ったのであった。","pages_en":["Her fingertips, without her knowing,\nrelayed her own pulse.\nAnd the girl wondered ─\nwhether her pulse, too,","was passing to the print itself."],"text_en":"Her fingertips, without her knowing,\nrelayed her own pulse.\nAnd the girl wondered ─\nwhether her pulse, too,\nwas passing to the print itself."}]},{"title":"第十四章 ─ 障子越しの視線","folder":"chapter_13","taps":[{"no":1,"img":"assets/images/chapter_13/IMG-103.webp","pages":["夜更けの座牢の障子に、\nひとつの影が静かに映った。\n障子の向こうに立つ人物は、\n叔父であった。","叔父は座牢の障子の前で、\n長く長く、その場に佇んでいる。\nただ、佇むのみで、\n一言の言葉も発さなかった。","障子の向こうの叔父の眼には、\nふと、幼き日のことが過ぎる。\n気まぐれに贈った土産を、娘はいまも、\n大切にしてくれている。"],"text":"夜更けの座牢の障子に、\nひとつの影が静かに映った。\n障子の向こうに立つ人物は、\n叔父であった。\n叔父は座牢の障子の前で、\n長く長く、その場に佇んでいる。\nただ、佇むのみで、\n一言の言葉も発さなかった。\n障子の向こうの叔父の眼には、\nふと、幼き日のことが過ぎる。\n気まぐれに贈った土産を、娘はいまも、\n大切にしてくれている。","pages_en":["Late that night, on the Cell's paper door,\na shadow silently appeared.\nThe figure beyond the door\nwas the uncle.","He stood there long,\nbefore the paper of the Cell.\nHe merely stood ─\nno word passed his lips.","In the uncle's eyes,\na childhood day flickered by.\nA gift given once, on a whim,\nthe girl still held dear."],"text_en":"Late that night, on the Cell's paper door,\na shadow silently appeared.\nThe figure beyond the door\nwas the uncle.\nHe stood there long,\nbefore the paper of the Cell.\nHe merely stood ─\nno word passed his lips.\nIn the uncle's eyes,\na childhood day flickered by.\nA gift given once, on a whim,\nthe girl still held dear."},{"no":2,"img":"assets/images/chapter_13/IMG-104.webp","pages":["座牢の中の娘は、\n桐の小箱を膝の上に置き、\n螺鈿の貝殻をそっと撫でていた。"],"text":"座牢の中の娘は、\n桐の小箱を膝の上に置き、\n螺鈿の貝殻をそっと撫でていた。","pages_en":["Within the Cell,\nthe girl set the paulownia box\nupon her lap\nand softly stroked the mother-of-pearl shell."],"text_en":"Within the Cell,\nthe girl set the paulownia box\nupon her lap\nand softly stroked the mother-of-pearl shell."},{"no":3,"img":"assets/images/chapter_13/IMG-105.webp","pages":["やがて、何の言葉も交わさぬままに、\n叔父の影は静かに消えてゆく。\n影が去ったあとの座牢には、\n月光がひとすじ、斜めに差し込んでいた。","娘はその光をなぞるように指を伸ばし、\n貝殻にそっと触れる。\n貝殻の縁は、月光と同じ温度を\nしていたのであった。"],"text":"やがて、何の言葉も交わさぬままに、\n叔父の影は静かに消えてゆく。\n影が去ったあとの座牢には、\n月光がひとすじ、斜めに差し込んでいた。\n娘はその光をなぞるように指を伸ばし、\n貝殻にそっと触れる。\n貝殻の縁は、月光と同じ温度を\nしていたのであった。","pages_en":["Before long, without a single word,\nthe uncle's shadow quietly withdrew.\nAfter he was gone,\na single stripe of moonlight","fell slanting into the Cell.\nAs though tracing the light,\nshe reached her finger\nand touched the shell.","The edge of the shell\nheld the same warmth\nas the moonlight itself."],"text_en":"Before long, without a single word,\nthe uncle's shadow quietly withdrew.\nAfter he was gone,\na single stripe of moonlight\nfell slanting into the Cell.\nAs though tracing the light,\nshe reached her finger\nand touched the shell.\nThe edge of the shell\nheld the same warmth\nas the moonlight itself."}]},{"title":"第十五章 ─ 煙管の音","folder":"chapter_14","taps":[{"no":1,"img":"assets/images/chapter_14/IMG-106.webp","pages":["翌朝、屋敷の南面の祖父の書斎では、\n煙管を叩く短い音が、いくたびも畳の上に\n響いていた。"],"text":"翌朝、屋敷の南面の祖父の書斎では、\n煙管を叩く短い音が、いくたびも畳の上に\n響いていた。","pages_en":["The next morning, in the south study,\nthe short crack of a pipe struck the tatami\nagain and again."],"text_en":"The next morning, in the south study,\nthe short crack of a pipe struck the tatami\nagain and again."},{"no":2,"img":"assets/images/chapter_14/IMG-107.webp","pages":["祖父の前では叔父が膝をついて控えていた。\n叔父を呼び出した祖父は静かに口を開いた。\n「お前様、近頃、蔵に頻りに出入りしておる\nそうじゃな」","祖父の声に怒気はないが、冷たく鋭かった。\n「お前様も、その血が騒ぐように\nなったというわけか……。\nま、せいぜい気をつけられよ」","叔父の応えは、震えてしか出てこなかった。\n「な、何のことやら、御祖父様、私は……」\n祖父はもう何も言わず、煙管の先端を、\n火桶の縁に軽く叩きつけた。"],"text":"祖父の前では叔父が膝をついて控えていた。\n叔父を呼び出した祖父は静かに口を開いた。\n「お前様、近頃、蔵に頻りに出入りしておる\nそうじゃな」\n祖父の声に怒気はないが、冷たく鋭かった。\n「お前様も、その血が騒ぐように\nなったというわけか……。\nま、せいぜい気をつけられよ」\n叔父の応えは、震えてしか出てこなかった。\n「な、何のことやら、御祖父様、私は……」\n祖父はもう何も言わず、煙管の先端を、\n火桶の縁に軽く叩きつけた。","pages_en":["Before Grandfather,\nthe uncle knelt low.\nHaving summoned him, Grandfather\nspoke without rising.","\"You have been visiting the storehouse\nquite often of late.\"\nThere was no anger in his voice ─\nonly cold and sharp intent.","\"So you, too, have begun to feel\nthe stirring of your blood…\nTake care.\"\nThe uncle's reply came only in tremors.","\"W-what can you mean?\nGrandfather, I…\"\nGrandfather said nothing more,\nand tapped his pipe on the brazier's rim."],"text_en":"Before Grandfather,\nthe uncle knelt low.\nHaving summoned him, Grandfather\nspoke without rising.\n\"You have been visiting the storehouse\nquite often of late.\"\nThere was no anger in his voice ─\nonly cold and sharp intent.\n\"So you, too, have begun to feel\nthe stirring of your blood…\nTake care.\"\nThe uncle's reply came only in tremors.\n\"W-what can you mean?\nGrandfather, I…\"\nGrandfather said nothing more,\nand tapped his pipe on the brazier's rim."},{"no":3,"img":"assets/images/chapter_14/IMG-108.webp","pages":["書斎を出た叔父は、何事もなかったように、\nいつもの調子で廊下を歩んだ。しかし、\n不意に全身の力が抜け落ち、叔父はとうとう\n座牢の前で崩れ落ちた。"],"text":"書斎を出た叔父は、何事もなかったように、\nいつもの調子で廊下を歩んだ。しかし、\n不意に全身の力が抜け落ち、叔父はとうとう\n座牢の前で崩れ落ちた。","pages_en":["Leaving the study, the uncle walked the hall\nas though nothing had passed.\nBut without warning\nall strength drained from him,","and he collapsed at last\nbefore the Cell."],"text_en":"Leaving the study, the uncle walked the hall\nas though nothing had passed.\nBut without warning\nall strength drained from him,\nand he collapsed at last\nbefore the Cell."},{"no":4,"img":"assets/images/chapter_14/IMG-109.webp","pages":["叔父の背は、肩のあたりが震えている。\n座牢の中の娘は、ふと、\n格子の隙間から指をそっと伸ばした。"],"text":"叔父の背は、肩のあたりが震えている。\n座牢の中の娘は、ふと、\n格子の隙間から指をそっと伸ばした。","pages_en":["His shoulders shook.\nIn the Cell, the girl\nquietly reached her finger\nthrough the lattice."],"text_en":"His shoulders shook.\nIn the Cell, the girl\nquietly reached her finger\nthrough the lattice."},{"no":5,"img":"assets/images/chapter_14/IMG-110.webp","pages":["けれども、その指は叔父の影には\n届かなかった。ただ廊下の冷えた空気に、\n触れただけであった。","空気の冷たさは、母の指の冷たさとも、\nまた違うものを宿していたのであった。"],"text":"けれども、その指は叔父の影には\n届かなかった。ただ廊下の冷えた空気に、\n触れただけであった。\n空気の冷たさは、母の指の冷たさとも、\nまた違うものを宿していたのであった。","pages_en":["But her finger did not reach him.\nIt met only the cold air\nof the corridor.","That cold\nheld a substance different\nfrom the cold of her mother's fingers."],"text_en":"But her finger did not reach him.\nIt met only the cold air\nof the corridor.\nThat cold\nheld a substance different\nfrom the cold of her mother's fingers."}]},{"title":"第十六章 ─ 贈り物","folder":"chapter_15","taps":[{"no":1,"img":"assets/images/chapter_15/IMG-111.webp","pages":["その日の夕暮れ、座牢を覆う障子が、\nふいに外側から開いた。\n障子の縁には、酒臭い息が、\nうっすらと漂っている。"],"text":"その日の夕暮れ、座牢を覆う障子が、\nふいに外側から開いた。\n障子の縁には、酒臭い息が、\nうっすらと漂っている。","pages_en":["That evening, the paper door of the Cell\nopened suddenly from without.\nThe scent of sake\nfaintly drifted at the seam."],"text_en":"That evening, the paper door of the Cell\nopened suddenly from without.\nThe scent of sake\nfaintly drifted at the seam."},{"no":2,"img":"assets/images/chapter_15/IMG-112.webp","pages":["障子を開いたのは、叔父であった。\n叔父は冷えた床に膝をつき、\n座牢の中の娘を静かに見る。\n叔父は、しばらく何も言わなかった。"],"text":"障子を開いたのは、叔父であった。\n叔父は冷えた床に膝をつき、\n座牢の中の娘を静かに見る。\n叔父は、しばらく何も言わなかった。","pages_en":["It was the uncle who had opened it.\nHe knelt on the chill floorboards\nand looked upon the girl.\nHe said nothing for a long while."],"text_en":"It was the uncle who had opened it.\nHe knelt on the chill floorboards\nand looked upon the girl.\nHe said nothing for a long while."},{"no":3,"img":"assets/images/chapter_15/IMG-113.webp","pages":["叔父はやがて、懐から紙の束を取り出し、\n格子戸に付けられた小窓から、\n娘の膝の前へとそっと差し入れた。\n書生が訳した、古文書の写しであった。","「これは……」\n叔父の声は、酒に濡れていた。\n「ろくでなしの、一矢報いる試みじゃ」"],"text":"叔父はやがて、懐から紙の束を取り出し、\n格子戸に付けられた小窓から、\n娘の膝の前へとそっと差し入れた。\n書生が訳した、古文書の写しであった。\n「これは……」\n叔父の声は、酒に濡れていた。\n「ろくでなしの、一矢報いる試みじゃ」","pages_en":["At last he drew from his robe\na sheaf of papers,\nand slid it through the small hatch\ninto the girl's lap.","It was a copy of the old text,\ntranslated by the student.\n\"This is…\"\nThe uncle's voice was wet with sake.","\"A wretch's attempt\nat one last blow of resistance.\""],"text_en":"At last he drew from his robe\na sheaf of papers,\nand slid it through the small hatch\ninto the girl's lap.\nIt was a copy of the old text,\ntranslated by the student.\n\"This is…\"\nThe uncle's voice was wet with sake.\n\"A wretch's attempt\nat one last blow of resistance.\""},{"no":4,"img":"assets/images/chapter_15/IMG-114.webp","pages":["それだけを告げると、叔父は立ち上がり、\n座牢の障子を静かに閉じた。\n障子を閉じる手つきは、\nやけに丁寧であった。","座牢にひとり残された娘は、\n両腕で紙の束を抱きしめる。"],"text":"それだけを告げると、叔父は立ち上がり、\n座牢の障子を静かに閉じた。\n障子を閉じる手つきは、\nやけに丁寧であった。\n座牢にひとり残された娘は、\n両腕で紙の束を抱きしめる。","pages_en":["Saying only that, he rose\nand quietly closed the paper door.\nHis hand upon the door\nmoved with strange gentleness.","Left alone within the Cell,\nthe girl held the papers to her chest."],"text_en":"Saying only that, he rose\nand quietly closed the paper door.\nHis hand upon the door\nmoved with strange gentleness.\nLeft alone within the Cell,\nthe girl held the papers to her chest."},{"no":5,"img":"assets/images/chapter_15/IMG-115.webp","pages":["その紙の上に、桐の小箱から取り出した\n螺鈿の貝殻を、そっと重ねた。"],"text":"その紙の上に、桐の小箱から取り出した\n螺鈿の貝殻を、そっと重ねた。","pages_en":["Upon them she gently placed\nthe mother-of-pearl shell\nfrom the paulownia box."],"text_en":"Upon them she gently placed\nthe mother-of-pearl shell\nfrom the paulownia box."},{"no":6,"img":"assets/images/chapter_15/IMG-116.webp","pages":["廊下の奥へと去ってゆく叔父の歩みは、\nこれまでとは違い、やけに軽やかに見えた。\nそれとは裏腹に、娘の心の中には、\n不安の種が静かに育ち始めていた。"],"text":"廊下の奥へと去ってゆく叔父の歩みは、\nこれまでとは違い、やけに軽やかに見えた。\nそれとは裏腹に、娘の心の中には、\n不安の種が静かに育ち始めていた。","pages_en":["The uncle's step down the hall\nseemed strangely light this night ─\nquite unlike before.\nAnd yet, within the girl's breast,","a quiet seed of unease\nhad begun to take root."],"text_en":"The uncle's step down the hall\nseemed strangely light this night ─\nquite unlike before.\nAnd yet, within the girl's breast,\na quiet seed of unease\nhad begun to take root."}]},{"title":"第十七章 ─ 梁の影","folder":"chapter_16","taps":[{"no":1,"img":"assets/images/chapter_16/IMG-117.webp","pages":["翌朝、屋敷の納屋の方から、\n女中の悲鳴がひとつ上がった。\n続いて、別の女中の声が激しく飛ぶ。\n「人が、人が、梁に……」","梁から下がっていたのは、叔父であった。\n座牢に近い納屋の梁に、首を吊って、\nゆっくりと揺れている。"],"text":"翌朝、屋敷の納屋の方から、\n女中の悲鳴がひとつ上がった。\n続いて、別の女中の声が激しく飛ぶ。\n「人が、人が、梁に……」\n梁から下がっていたのは、叔父であった。\n座牢に近い納屋の梁に、首を吊って、\nゆっくりと揺れている。","pages_en":["The next morning, from the storehouse\ncame the scream of a maid.\nAnother maid's voice followed:\n\"A person ─ upon the beam ─\"","From the beam of a shed\nnear the Cell hung the uncle,\na rope about his neck,\nswaying slowly."],"text_en":"The next morning, from the storehouse\ncame the scream of a maid.\nAnother maid's voice followed:\n\"A person ─ upon the beam ─\"\nFrom the beam of a shed\nnear the Cell hung the uncle,\na rope about his neck,\nswaying slowly."},{"no":2,"img":"assets/images/chapter_16/IMG-118.webp","pages":["叔父の手には、書生に渡そうとしたらしい\n古文書の一片が、握り締められていた。\n家族の突然の死。だが、屋敷の者の多くは、\n感心を示そうともしなかった。"],"text":"叔父の手には、書生に渡そうとしたらしい\n古文書の一片が、握り締められていた。\n家族の突然の死。だが、屋敷の者の多くは、\n感心を示そうともしなかった。","pages_en":["In his hand, still gripped,\nwas a fragment of the old text\nhe had meant to pass to the student.\nA sudden death in the family.","Yet most in the manor\nshowed no interest at all."],"text_en":"In his hand, still gripped,\nwas a fragment of the old text\nhe had meant to pass to the student.\nA sudden death in the family.\nYet most in the manor\nshowed no interest at all."},{"no":3,"img":"assets/images/chapter_09/IMG-079.webp","pages":["父は黙して盃を傾け、\n祖父は煙の中に目を細めている。"],"text":"父は黙して盃を傾け、\n祖父は煙の中に目を細めている。","pages_en":["The father held silent, cup at his lips.\nGrandfather narrowed his eyes\nwithin the smoke."],"text_en":"The father held silent, cup at his lips.\nGrandfather narrowed his eyes\nwithin the smoke."},{"no":4,"img":"assets/images/chapter_09/IMG-078.webp","pages":["叔母は、異様に冷静な顔つきで、\n葬儀の手配を始めてゆく。"],"text":"叔母は、異様に冷静な顔つきで、\n葬儀の手配を始めてゆく。","pages_en":["The aunt, with startling composure,\nbegan to arrange the funeral."],"text_en":"The aunt, with startling composure,\nbegan to arrange the funeral."},{"no":5,"img":"assets/images/chapter_16/IMG-119.webp","pages":["座牢に残された娘は、\n桐の小箱をいっそう深く抱きしめていた。"],"text":"座牢に残された娘は、\n桐の小箱をいっそう深く抱きしめていた。","pages_en":["Within the Cell,\nthe girl held the paulownia box\nyet more tightly to her chest."],"text_en":"Within the Cell,\nthe girl held the paulownia box\nyet more tightly to her chest."},{"no":6,"img":"assets/images/chapter_16/IMG-119.webp","pages":["小箱の中では、螺鈿の貝殻と\n古文書の写しとが、寄り添うように\n重なり合っていたのであった。"],"text":"小箱の中では、螺鈿の貝殻と\n古文書の写しとが、寄り添うように\n重なり合っていたのであった。","pages_en":["Within the box,\nthe mother-of-pearl shell\nand the copy of the old text\nlay overlapping, as though for shelter."],"text_en":"Within the box,\nthe mother-of-pearl shell\nand the copy of the old text\nlay overlapping, as though for shelter."}]},{"title":"第十八章 ─ 紅き廊下と祭壇の前","folder":"chapter_17","taps":[{"no":1,"img":"assets/images/chapter_17/IMG-120.webp","pages":["数日が過ぎた夜、奥座敷では、\n父が祖父の前で深く頭を下げていた。"],"text":"数日が過ぎた夜、奥座敷では、\n父が祖父の前で深く頭を下げていた。","pages_en":["A few days on, in the inner parlor,\nthe father bowed deeply\nbefore Grandfather."],"text_en":"A few days on, in the inner parlor,\nthe father bowed deeply\nbefore Grandfather."},{"no":2,"img":"assets/images/chapter_17/IMG-120.webp","pages":["父がようやく、\n祖父の眼力を曇らせるほどの、\n大きな商談をひとつ成し遂げたのであった。"],"text":"父がようやく、\n祖父の眼力を曇らせるほどの、\n大きな商談をひとつ成し遂げたのであった。","pages_en":["The father had at last brought off\na great transaction ─\none large enough\nto dim even Grandfather's eyes."],"text_en":"The father had at last brought off\na great transaction ─\none large enough\nto dim even Grandfather's eyes."},{"no":3,"img":"assets/images/chapter_17/IMG-121.webp","pages":["けれども、屋敷の中の歯車は、\nその日を境にいっそう乱れてゆく。\n父に対する祖父の期待が膨らむほどに、\n父は自暴自棄に酒を呷る。","父にとって、酒だけが、\n唯一許された逃げ道であった。"],"text":"けれども、屋敷の中の歯車は、\nその日を境にいっそう乱れてゆく。\n父に対する祖父の期待が膨らむほどに、\n父は自暴自棄に酒を呷る。\n父にとって、酒だけが、\n唯一許された逃げ道であった。","pages_en":["Yet from that day, the gears within\nthe manor slid further out of true.\nAs Grandfather's hopes for his son grew,\nso the father drank the more","in wild abandon.\nDrink, for him,\nhad become the only path\nof escape left open."],"text_en":"Yet from that day, the gears within\nthe manor slid further out of true.\nAs Grandfather's hopes for his son grew,\nso the father drank the more\nin wild abandon.\nDrink, for him,\nhad become the only path\nof escape left open."},{"no":4,"img":"assets/images/chapter_17/IMG-122.webp","pages":["廊下の彼方では、女中の衣擦れの音が、\n祖父の寝所より細く漏れる。\n祖父の眼の緩みは、屋敷の他の所作にも、\nじわりじわりと伝染していった。","別の廊下の奥では、叔母と書生が、\n互いを見つめ合い、体を絡め合っていた。"],"text":"廊下の彼方では、女中の衣擦れの音が、\n祖父の寝所より細く漏れる。\n祖父の眼の緩みは、屋敷の他の所作にも、\nじわりじわりと伝染していった。\n別の廊下の奥では、叔母と書生が、\n互いを見つめ合い、体を絡め合っていた。","pages_en":["From the far end of the hall,\nthe rustle of a maid's kimono\nleaked thinly from Grandfather's room.\nGrandfather's slackening of vigilance","seeped, drop by drop,\ninto the manor's other acts.\nDown another hallway,\nthe aunt and the student","gazed into each other's eyes\nand tangled their bodies together."],"text_en":"From the far end of the hall,\nthe rustle of a maid's kimono\nleaked thinly from Grandfather's room.\nGrandfather's slackening of vigilance\nseeped, drop by drop,\ninto the manor's other acts.\nDown another hallway,\nthe aunt and the student\ngazed into each other's eyes\nand tangled their bodies together."},{"no":5,"img":"assets/images/chapter_17/IMG-123.webp","pages":["幼き弟妹は、異変の兆しを僅かに察し、\n布団の中で身を震わせている。\nそんな夜、母は座牢を訪れ、格子の前で\nしばし立ち止まった。"],"text":"幼き弟妹は、異変の兆しを僅かに察し、\n布団の中で身を震わせている。\nそんな夜、母は座牢を訪れ、格子の前で\nしばし立ち止まった。","pages_en":["The younger siblings, sensing something,\ntrembled beneath their quilts.\nOn such a night, the mother came\nto the Cell and paused before the lattice."],"text_en":"The younger siblings, sensing something,\ntrembled beneath their quilts.\nOn such a night, the mother came\nto the Cell and paused before the lattice."},{"no":6,"img":"assets/images/chapter_17/IMG-124.webp","pages":["娘は格子に身を寄せ、母を見上げる。\n「弟妹を父様の側に、寝かせてあげては」\n母は目を伏せて応えた。「あの方は、\n私が傍にいることも拒まれておられる」と。"],"text":"娘は格子に身を寄せ、母を見上げる。\n「弟妹を父様の側に、寝かせてあげては」\n母は目を伏せて応えた。「あの方は、\n私が傍にいることも拒まれておられる」と。","pages_en":["The girl leaned to the bars and looked up.\n\"Might the young ones sleep\nby Father's side?\"\nThe mother, eyes lowered, replied:","\"He rejects even my presence\nat his side.\""],"text_en":"The girl leaned to the bars and looked up.\n\"Might the young ones sleep\nby Father's side?\"\nThe mother, eyes lowered, replied:\n\"He rejects even my presence\nat his side.\""},{"no":7,"img":"assets/images/chapter_17/IMG-125.webp","pages":["同じ夜、屋敷の祭壇の前では、\n呪言を呟く兄が座していた。"],"text":"同じ夜、屋敷の祭壇の前では、\n呪言を呟く兄が座していた。","pages_en":["That same night, before the altar,\nthe elder brother sat,\nmurmuring incantations."],"text_en":"That same night, before the altar,\nthe elder brother sat,\nmurmuring incantations."},{"no":8,"img":"assets/images/chapter_17/IMG-125.webp","pages":["父の酒杯の音、女中の衣擦れ、\n叔母の火照った囁き、そのすべてを\n祓うように、兄は真っすぐに\n祭壇を見つめていた。","兄の口元からは、\n誰にも届かない独語が、\n微かに――だが、確かに漏れている。"],"text":"父の酒杯の音、女中の衣擦れ、\n叔母の火照った囁き、そのすべてを\n祓うように、兄は真っすぐに\n祭壇を見つめていた。\n兄の口元からは、\n誰にも届かない独語が、\n微かに――だが、確かに漏れている。","pages_en":["The father's cup, the maid's rustle,\nthe aunt's heated whisper ─\nas though to purge all these,\nthe brother gazed straight at the altar.","From his lips,\na private speech, meant for no one,\nescaped ─ faint, but certain."],"text_en":"The father's cup, the maid's rustle,\nthe aunt's heated whisper ─\nas though to purge all these,\nthe brother gazed straight at the altar.\nFrom his lips,\na private speech, meant for no one,\nescaped ─ faint, but certain."},{"no":9,"img":"assets/images/chapter_17/IMG-126.webp","pages":["娘が格子越しに伸ばした指を、\n母がそっと握り返した。\n母の指は冷たく、その冷たさは\n廊下の冷えとは別のものを宿していた。"],"text":"娘が格子越しに伸ばした指を、\n母がそっと握り返した。\n母の指は冷たく、その冷たさは\n廊下の冷えとは別のものを宿していた。","pages_en":["Through the lattice\nthe girl's finger reached out,\nand the mother returned its touch.\nHer fingers were cold,","and that cold held something different\nfrom the chill of the hall."],"text_en":"Through the lattice\nthe girl's finger reached out,\nand the mother returned its touch.\nHer fingers were cold,\nand that cold held something different\nfrom the chill of the hall."},{"no":10,"img":"assets/images/chapter_17/IMG-127.webp","pages":["冷たさの中には、長く隠されてきた\n何ものかが、息を潜めていたのであった。"],"text":"冷たさの中には、長く隠されてきた\n何ものかが、息を潜めていたのであった。","pages_en":["Within that cold,\nsomething long hidden\nhad drawn its breath in silence."],"text_en":"Within that cold,\nsomething long hidden\nhad drawn its breath in silence."}]},{"title":"第十九章 ─ 病床","folder":"chapter_18","taps":[{"no":1,"img":"assets/images/chapter_18/IMG-128.webp","pages":["ある朝、祖母の寝所では、\n祖母が床から起き上がらぬままに、\n朝の光を浴びていた。かねてより\n「もう年じゃ」と笑うていた祖母である。"],"text":"ある朝、祖母の寝所では、\n祖母が床から起き上がらぬままに、\n朝の光を浴びていた。かねてより\n「もう年じゃ」と笑うていた祖母である。","pages_en":["One morning, in Grandmother's chamber,\nshe did not rise from her bed,\nbut lay bathed in the morning light.\nShe who had laughed \"I am old now\"","remained still."],"text_en":"One morning, in Grandmother's chamber,\nshe did not rise from her bed,\nbut lay bathed in the morning light.\nShe who had laughed \"I am old now\"\nremained still."},{"no":2,"img":"assets/images/chapter_18/IMG-129.webp","pages":["朝餉の刻になっても起きてこない\n祖母を案じて母が座牢の格子戸を開いた。\n「お前様、御祖母様の枕元へ」\n母はそう、静かに告げた。","祖母の寝所へ赴くは、\n娘にとって久しぶりのことであった。\n祖母の枕元に、娘は静かに膝を折る。\n祖母の眼は、もはや虚ろであった。","「来てくれたか、お前」\nそれだけを、祖母は呟いた。\n娘がそっと祖母の手を取ると、骨の節が、\n薄き皮膚の下にくっきりと浮かんでいる。"],"text":"朝餉の刻になっても起きてこない\n祖母を案じて母が座牢の格子戸を開いた。\n「お前様、御祖母様の枕元へ」\n母はそう、静かに告げた。\n祖母の寝所へ赴くは、\n娘にとって久しぶりのことであった。\n祖母の枕元に、娘は静かに膝を折る。\n祖母の眼は、もはや虚ろであった。\n「来てくれたか、お前」\nそれだけを、祖母は呟いた。\n娘がそっと祖母の手を取ると、骨の節が、\n薄き皮膚の下にくっきりと浮かんでいる。","pages_en":["When she did not come to the morning meal,\nthe mother opened the Cell.\n\"Come, my child, to Grandmother's side.\"\nSo she said, quietly.","It had been long\nsince the girl had gone\nto Grandmother's bedside.\nShe knelt in silence at the pillow.","Grandmother's eyes were already vacant.\n\"You came, my child,\"\nshe murmured, and that was all.\nAs the girl took her hand,","the joints of the bones stood out\nsharply beneath thin skin."],"text_en":"When she did not come to the morning meal,\nthe mother opened the Cell.\n\"Come, my child, to Grandmother's side.\"\nSo she said, quietly.\nIt had been long\nsince the girl had gone\nto Grandmother's bedside.\nShe knelt in silence at the pillow.\nGrandmother's eyes were already vacant.\n\"You came, my child,\"\nshe murmured, and that was all.\nAs the girl took her hand,\nthe joints of the bones stood out\nsharply beneath thin skin."},{"no":3,"img":"assets/images/chapter_18/IMG-130.webp","pages":["「お前に言わねばならぬことが……」\n弱々しく語る祖母の口元が、\n何かを言いかけて、止まった。\n「いえ……今は、よい」と。"],"text":"「お前に言わねばならぬことが……」\n弱々しく語る祖母の口元が、\n何かを言いかけて、止まった。\n「いえ……今は、よい」と。","pages_en":["\"There is something I must tell you…\"\nGrandmother's weak lips began,\nthen stopped.\n\"No… not now,\" she said."],"text_en":"\"There is something I must tell you…\"\nGrandmother's weak lips began,\nthen stopped.\n\"No… not now,\" she said."},{"no":4,"img":"assets/images/chapter_18/IMG-130.webp","pages":["娘は、長く、祖母の枕元に\n座り続けていた。"],"text":"娘は、長く、祖母の枕元に\n座り続けていた。","pages_en":["The girl remained long\nat Grandmother's bedside."],"text_en":"The girl remained long\nat Grandmother's bedside."},{"no":5,"img":"assets/images/chapter_18/IMG-131.webp","pages":["祖母が語るのをやめた後、\n廊下の彼方では、祭壇の灯が\n何ものかに揺らされたように、\nふいと震えていた。","座牢に戻る道すがら、娘の耳には、\n祖母のかすかな息音だけが、\nまだ残っていたのであった。"],"text":"祖母が語るのをやめた後、\n廊下の彼方では、祭壇の灯が\n何ものかに揺らされたように、\nふいと震えていた。\n座牢に戻る道すがら、娘の耳には、\n祖母のかすかな息音だけが、\nまだ残っていたのであった。","pages_en":["After Grandmother ceased to speak,\nfar down the hall\nthe altar's lamp shuddered once,\nas though shaken by something unseen.","On the way back to the Cell,\nonly Grandmother's faint breath\nstill remained\nin the girl's ear."],"text_en":"After Grandmother ceased to speak,\nfar down the hall\nthe altar's lamp shuddered once,\nas though shaken by something unseen.\nOn the way back to the Cell,\nonly Grandmother's faint breath\nstill remained\nin the girl's ear."}]},{"title":"第二十章 ─ 嫁入りと囁き","folder":"chapter_19","taps":[{"no":1,"img":"assets/images/chapter_19/IMG-132.webp","pages":["数日が過ぎた昼下がり、\n屋敷の塀の外を、嫁入りの行列が\n華やかな空気と共に通って行った。\n白無垢の花嫁が、駕籠に揺られている。","三味の音と、賑やかな祝いの声が、\n屋敷の塀の内側にも遠く伝わる。\n座牢の高窓越しに、娘はその列を\nじっと見つめていた。"],"text":"数日が過ぎた昼下がり、\n屋敷の塀の外を、嫁入りの行列が\n華やかな空気と共に通って行った。\n白無垢の花嫁が、駕籠に揺られている。\n三味の音と、賑やかな祝いの声が、\n屋敷の塀の内側にも遠く伝わる。\n座牢の高窓越しに、娘はその列を\nじっと見つめていた。","pages_en":["A few days later, one afternoon,\nbeyond the manor wall passed\na bridal procession,\ncarrying its festive air.","A bride in white robes\nwas borne in a palanquin.\nThe sound of shamisen and\nthe voices of celebration","drifted faintly\nto the inside of the wall.\nThrough the high window of the Cell,\nthe girl watched the procession."],"text_en":"A few days later, one afternoon,\nbeyond the manor wall passed\na bridal procession,\ncarrying its festive air.\nA bride in white robes\nwas borne in a palanquin.\nThe sound of shamisen and\nthe voices of celebration\ndrifted faintly\nto the inside of the wall.\nThrough the high window of the Cell,\nthe girl watched the procession."},{"no":2,"img":"assets/images/chapter_19/IMG-133.webp","pages":["「いつかは、白無垢に身を包み、\n屋敷の門をくぐる日が来るはず」\n娘は誰にも届かぬ声で、\n独語を零す。"],"text":"「いつかは、白無垢に身を包み、\n屋敷の門をくぐる日が来るはず」\n娘は誰にも届かぬ声で、\n独語を零す。","pages_en":["\"One day, I too, robed in white,\nshall pass through the manor's gate.\"\nShe let the murmur escape,\ntoward no ear at all."],"text_en":"\"One day, I too, robed in white,\nshall pass through the manor's gate.\"\nShe let the murmur escape,\ntoward no ear at all."},{"no":3,"img":"assets/images/chapter_19/IMG-134.webp","pages":["その独語の余韻もまだ消えぬ夕暮れに、\n屋敷の祭壇の前には、\nまたひとつの影が現れた。\n父が妾に産ませた、腹違いの兄である。","兄はそのつねのごとく、\n無言で祭壇の燈明を整えていた。"],"text":"その独語の余韻もまだ消えぬ夕暮れに、\n屋敷の祭壇の前には、\nまたひとつの影が現れた。\n父が妾に産ませた、腹違いの兄である。\n兄はそのつねのごとく、\n無言で祭壇の燈明を整えていた。","pages_en":["Before the echo of that murmur had faded,\ntoward evening,\nbefore the altar of the manor\nyet another shadow appeared.","It was the elder brother,\nborn to the father's concubine."],"text_en":"Before the echo of that murmur had faded,\ntoward evening,\nbefore the altar of the manor\nyet another shadow appeared.\nIt was the elder brother,\nborn to the father's concubine."},{"no":4,"img":"assets/images/chapter_19/IMG-135.webp","pages":["けれども、今夜の兄の眼には、\nこれまでとは違う色が湛えられている。"],"text":"けれども、今夜の兄の眼には、\nこれまでとは違う色が湛えられている。","pages_en":["As always he tended the altar's lamp\nin silence.\nYet in his eyes tonight\ndwelt a color unlike any before."],"text_en":"As always he tended the altar's lamp\nin silence.\nYet in his eyes tonight\ndwelt a color unlike any before."},{"no":5,"img":"assets/images/chapter_19/IMG-136.webp","pages":["兄は祭壇の前から、ふいに振り返り、\n座牢の方角を真っ直ぐに見据える。\nそして、唐突に廊下を駆け出し――、\n瞬く間に座牢の前に立った。"],"text":"兄は祭壇の前から、ふいに振り返り、\n座牢の方角を真っ直ぐに見据える。\nそして、唐突に廊下を駆け出し――、\n瞬く間に座牢の前に立った。","pages_en":["Suddenly he turned from the altar\nand fixed his gaze\nsquarely on the direction of the Cell.\nHe broke into a run down the hall ─","and in an instant\nstood before the Cell itself."],"text_en":"Suddenly he turned from the altar\nand fixed his gaze\nsquarely on the direction of the Cell.\nHe broke into a run down the hall ─\nand in an instant\nstood before the Cell itself."},{"no":6,"img":"assets/images/chapter_19/IMG-136.webp","pages":["「お前は、母様と同じだ。籠の鳥は、\n空の青さを知らずに、死ぬる定めよ」\n「真に外を望むなら──親指を、隠せ」"],"text":"「お前は、母様と同じだ。籠の鳥は、\n空の青さを知らずに、死ぬる定めよ」\n「真に外を望むなら──親指を、隠せ」","pages_en":["\"You are like your mother.\nThe caged bird dies\nwithout knowing the blue of the sky.\"","\"If you truly desire the outside ─\nhide your thumbs.\""],"text_en":"\"You are like your mother.\nThe caged bird dies\nwithout knowing the blue of the sky.\"\n\"If you truly desire the outside ─\nhide your thumbs.\""},{"no":7,"img":"assets/images/chapter_19/IMG-137.webp","pages":["その瞬間、幼き日の思い出が蘇った。\nそれは、霊柩の通る朝、母が娘の親指を\nそっと拳の中に折り込ませた、\nあの冷たい所作であった。"],"text":"その瞬間、幼き日の思い出が蘇った。\nそれは、霊柩の通る朝、母が娘の親指を\nそっと拳の中に折り込ませた、\nあの冷たい所作であった。","pages_en":["In that instant a memory revived ─\nof the morning the funeral bier passed,\nwhen the mother had gently folded\nthe girl's thumbs into her fists,","with that cold gesture."],"text_en":"In that instant a memory revived ─\nof the morning the funeral bier passed,\nwhen the mother had gently folded\nthe girl's thumbs into her fists,\nwith that cold gesture."},{"no":8,"img":"assets/images/chapter_19/IMG-138.webp","pages":["兄が祭壇の闇に消えたあとも、\n娘は自分の親指を、長く見つめていた。\n指の節は、幼き日に折られた節の位置を、\nいまだ覚えていたのであった。"],"text":"兄が祭壇の闇に消えたあとも、\n娘は自分の親指を、長く見つめていた。\n指の節は、幼き日に折られた節の位置を、\nいまだ覚えていたのであった。","pages_en":["Even after the brother\nvanished into the altar's dark,\nthe girl gazed long\nat her own thumb.","The joints of her fingers\nstill remembered the very place\nwhere they had been folded,\nin her childhood."],"text_en":"Even after the brother\nvanished into the altar's dark,\nthe girl gazed long\nat her own thumb.\nThe joints of her fingers\nstill remembered the very place\nwhere they had been folded,\nin her childhood."}]},{"title":"第二十一章 ─ 祖母の手","folder":"chapter_20","taps":[{"no":1,"img":"assets/images/chapter_20/IMG-139.webp","pages":["その夜、祖母の寝所の枕元には、\n家の者がひとり、ふたりと集まってきた。\n祖母の息はもう、糸のように細く、\n長く引いている。"],"text":"その夜、祖母の寝所の枕元には、\n家の者がひとり、ふたりと集まってきた。\n祖母の息はもう、糸のように細く、\n長く引いている。","pages_en":["That night, at Grandmother's pillow,\nthe family gathered ─ one, then two.\nHer breath was already a thread,\nspun long and thin."],"text_en":"That night, at Grandmother's pillow,\nthe family gathered ─ one, then two.\nHer breath was already a thread,\nspun long and thin."},{"no":2,"img":"assets/images/chapter_20/IMG-140.webp","pages":["祖母の枕元には、娘の姿もあった。\n母に手を引かれて、しずかに膝を折る。\n祖母は、娘の手を、\n思いがけぬほどの力で握りしめた。","「お前の前にも……」\n祖母の眼が、ふと、遠くを見つめる。\n「お前のような子が、おったのじゃ……。\n今のお前にようよう、似ておったよ」","その言葉を最後に、\n祖母の手はゆっくりと解けてゆく。\n屋敷に低い嗚咽がじわりと広がっていった。\n叔母の声だけは、ひとつも聞こえなかった。"],"text":"祖母の枕元には、娘の姿もあった。\n母に手を引かれて、しずかに膝を折る。\n祖母は、娘の手を、\n思いがけぬほどの力で握りしめた。\n「お前の前にも……」\n祖母の眼が、ふと、遠くを見つめる。\n「お前のような子が、おったのじゃ……。\n今のお前にようよう、似ておったよ」\nその言葉を最後に、\n祖母の手はゆっくりと解けてゆく。\n屋敷に低い嗚咽がじわりと広がっていった。\n叔母の声だけは、ひとつも聞こえなかった。","pages_en":["The girl, too, was at the pillow.\nLed by her mother,\nshe knelt down quietly.\nGrandmother closed her fingers about","the girl's hand,\nwith unlooked-for strength.\n\"Before you… there was another…\"\nHer eyes drifted far.","\"A child like you.\nMuch like you as you are now.\"","With that word, her last,\nGrandmother's hand slowly loosened.\nA low weeping spread through the manor.\nOnly the aunt's voice was not heard."],"text_en":"The girl, too, was at the pillow.\nLed by her mother,\nshe knelt down quietly.\nGrandmother closed her fingers about\nthe girl's hand,\nwith unlooked-for strength.\n\"Before you… there was another…\"\nHer eyes drifted far.\n\"A child like you.\nMuch like you as you are now.\"\nWith that word, her last,\nGrandmother's hand slowly loosened.\nA low weeping spread through the manor.\nOnly the aunt's voice was not heard."},{"no":3,"img":"assets/images/chapter_00_intro/IMG-009.webp","pages":["夜更け、座牢に戻った娘の隣室――、\n母の寝屋から、寝言がぽつりと漏れてきた。\n「ごめんね……ごめんね、たま……」と。","娘は息を殺し、母の声を\n心の奥に静かに留め置いた。\nそして、ぽつりと呟いた。\n「たま……」"],"text":"夜更け、座牢に戻った娘の隣室――、\n母の寝屋から、寝言がぽつりと漏れてきた。\n「ごめんね……ごめんね、たま……」と。\n娘は息を殺し、母の声を\n心の奥に静かに留め置いた。\nそして、ぽつりと呟いた。\n「たま……」","pages_en":["Late that night, in the room by the Cell,\nfrom the mother's own bedchamber,\na sleeping voice\nescaped in a small tremor.","\"Forgive me… forgive me, Tama…\"\nThe girl held her breath\nand quietly kept the mother's voice\ndeep within her chest.","And she murmured, low:\n\"Tama…\""],"text_en":"Late that night, in the room by the Cell,\nfrom the mother's own bedchamber,\na sleeping voice\nescaped in a small tremor.\n\"Forgive me… forgive me, Tama…\"\nThe girl held her breath\nand quietly kept the mother's voice\ndeep within her chest.\nAnd she murmured, low:\n\"Tama…\""},{"no":4,"img":"assets/images/chapter_20/IMG-141.webp","pages":["あの、霧の中で蹴り飛ばされた\n老猫の名でもある。\n娘の指は、闇の中でその名を\n心の中で呟くたびに、震えるのだった。"],"text":"あの、霧の中で蹴り飛ばされた\n老猫の名でもある。\n娘の指は、闇の中でその名を\n心の中で呟くたびに、震えるのだった。","pages_en":["It was also the name\nof the old cat kicked into the mist.\nEach time the girl whispered that name\nin the darkness of her heart,","her fingers trembled."],"text_en":"It was also the name\nof the old cat kicked into the mist.\nEach time the girl whispered that name\nin the darkness of her heart,\nher fingers trembled."}]},{"title":"第二十二章 ─ 葬列と発作","folder":"chapter_21","taps":[{"no":1,"img":"assets/images/chapter_01/IMG-014.webp","pages":["翌朝、屋敷の門前には、\n黒衣の客が静かに並んだ。坊主の経が、\n玄関先より座敷へと響き渡り、弔問の客が、\n廊下を絶え間なく行き来している。"],"text":"翌朝、屋敷の門前には、\n黒衣の客が静かに並んだ。坊主の経が、\n玄関先より座敷へと響き渡り、弔問の客が、\n廊下を絶え間なく行き来している。","pages_en":["The next morning, before the manor gate,\nblack-robed mourners stood in silence.\nThe sutra of a monk\nreached from the entrance to the parlor,","and mourners passed ceaselessly\nthrough the corridors."],"text_en":"The next morning, before the manor gate,\nblack-robed mourners stood in silence.\nThe sutra of a monk\nreached from the entrance to the parlor,\nand mourners passed ceaselessly\nthrough the corridors."},{"no":2,"img":"assets/images/chapter_21/IMG-142.webp","pages":["娘は座牢の高窓辺で、\n霊柩の車をじっと見送っていた。\n思わず、両の親指を拳の中に隠す。","幼き日、葬列を前に親指を隠し日――、\n「もう、その所作はなさるな」と、\n強く制止されたことが、ふいに蘇ってきた。\nいま、母が娘に声をかけることはなかった。"],"text":"娘は座牢の高窓辺で、\n霊柩の車をじっと見送っていた。\n思わず、両の親指を拳の中に隠す。\n幼き日、葬列を前に親指を隠し日――、\n「もう、その所作はなさるな」と、\n強く制止されたことが、ふいに蘇ってきた。\nいま、母が娘に声をかけることはなかった。","pages_en":["At the high window of the Cell,\nthe girl watched the funeral cart go.\nWithout thinking,\nshe folded her thumbs into her fists.","The day of her childhood,\nwhen a bier had passed the manor,\nand she had hidden her thumbs ─\nthat day, forbidden by her mother,","rose up again unbidden.\nThis time, the mother said\nnothing to her at all."],"text_en":"At the high window of the Cell,\nthe girl watched the funeral cart go.\nWithout thinking,\nshe folded her thumbs into her fists.\nThe day of her childhood,\nwhen a bier had passed the manor,\nand she had hidden her thumbs ─\nthat day, forbidden by her mother,\nrose up again unbidden.\nThis time, the mother said\nnothing to her at all."},{"no":3,"img":"assets/images/chapter_21/IMG-143.webp","pages":["葬列の最後尾には、兄が控えていた。\n兄の眼は、深く翳っている。\nあの祭壇の前で挑むように放った光は、\nもうそこにはなかった。","一度だけ、兄は娘の方を振り返り、\nすぐに目を伏せる。"],"text":"葬列の最後尾には、兄が控えていた。\n兄の眼は、深く翳っている。\nあの祭壇の前で挑むように放った光は、\nもうそこにはなかった。\n一度だけ、兄は娘の方を振り返り、\nすぐに目を伏せる。","pages_en":["At the tail of the procession\nwalked the elder brother.\nHis eyes were sunk in shadow.\nThe light that had once flared","before the altar\nwas nowhere to be seen.\nJust once, he turned to look\ntoward the Cell,","then quickly lowered his gaze."],"text_en":"At the tail of the procession\nwalked the elder brother.\nHis eyes were sunk in shadow.\nThe light that had once flared\nbefore the altar\nwas nowhere to be seen.\nJust once, he turned to look\ntoward the Cell,\nthen quickly lowered his gaze."},{"no":4,"img":"assets/images/chapter_21/IMG-144.webp","pages":["葬儀の終わり、廊下を行き過ぎる叔母が、\nふと座牢の前で足を止めた。\nそして唐突に声をかける。\n「お前さん……」"],"text":"葬儀の終わり、廊下を行き過ぎる叔母が、\nふと座牢の前で足を止めた。\nそして唐突に声をかける。\n「お前さん……」","pages_en":["At the funeral's end,\nas the aunt passed down the hall,\nshe stopped before the Cell.\nShe spoke, without warning:","\"You there…\""],"text_en":"At the funeral's end,\nas the aunt passed down the hall,\nshe stopped before the Cell.\nShe spoke, without warning:\n\"You there…\""},{"no":5,"img":"assets/images/chapter_21/IMG-145.webp","pages":["「お母様の御寝言、聞こえなんだか？」\n叔母の声は、笑みを含んでいる。\n娘は、思わず息を呑んだ。"],"text":"「お母様の御寝言、聞こえなんだか？」\n叔母の声は、笑みを含んでいる。\n娘は、思わず息を呑んだ。","pages_en":["\"Did you not hear\nyour mother's sleep-talk?\"\nA smile played in her voice.\nThe girl caught her breath despite herself."],"text_en":"\"Did you not hear\nyour mother's sleep-talk?\"\nA smile played in her voice.\nThe girl caught her breath despite herself."},{"no":6,"img":"assets/images/chapter_21/IMG-146.webp","pages":["その夜更け、父の寝所から、\n母の凄まじい声が響いた。\n「父様！」"],"text":"その夜更け、父の寝所から、\n母の凄まじい声が響いた。\n「父様！」","pages_en":["Late that night,\nfrom the father's chamber\nthe mother's sudden cry rang out:\n\"Father!\""],"text_en":"Late that night,\nfrom the father's chamber\nthe mother's sudden cry rang out:\n\"Father!\""},{"no":7,"img":"assets/images/chapter_21/IMG-146.webp","pages":["母が御抱の老医師を呼びに、\n廊下を駆け抜けてゆく。\n座牢の障子がその風で、僅かに震えた。"],"text":"母が御抱の老医師を呼びに、\n廊下を駆け抜けてゆく。\n座牢の障子がその風で、僅かに震えた。","pages_en":["She ran down the hall\nto fetch the old family physician.\nThe wind of her passing\ntrembled the paper of the Cell."],"text_en":"She ran down the hall\nto fetch the old family physician.\nThe wind of her passing\ntrembled the paper of the Cell."},{"no":8,"img":"assets/images/chapter_21/IMG-147.webp","pages":["震えの後に残された静けさの中で、\n娘は自らの拳の中の親指を、\nまだ解くことが叶わなかったのであった。"],"text":"震えの後に残された静けさの中で、\n娘は自らの拳の中の親指を、\nまだ解くことが叶わなかったのであった。","pages_en":["In the stillness left behind,\nthe girl could not yet\nunfold her thumbs\nfrom within her fists."],"text_en":"In the stillness left behind,\nthe girl could not yet\nunfold her thumbs\nfrom within her fists."}]},{"title":"第二十三章 ─ 詰問と告白","folder":"chapter_22","taps":[{"no":1,"img":"assets/images/chapter_22/IMG-148.webp","pages":["老医師は、父の寝所で脈を診て、\nゆっくりと首を振った。\n「これは、もう起き上がられぬ」"],"text":"老医師は、父の寝所で脈を診て、\nゆっくりと首を振った。\n「これは、もう起き上がられぬ」","pages_en":["The old physician took the father's pulse\nand slowly shook his head.\n\"He shall not rise again.\""],"text_en":"The old physician took the father's pulse\nand slowly shook his head.\n\"He shall not rise again.\""},{"no":2,"img":"assets/images/chapter_17/IMG-124.webp","pages":["父は人事不省のまま、\n寝所に静かに横たえられた。\n父の枕元では、母が父の手を取って、\n静かに握りしめている。","四十九日の席で、家の者は皆、\n黙して箸を運ばなかった。そんな中、\n番頭が、父の代わりに家業の差配を\n引き受け始めている。"],"text":"父は人事不省のまま、\n寝所に静かに横たえられた。\n父の枕元では、母が父の手を取って、\n静かに握りしめている。\n四十九日の席で、家の者は皆、\n黙して箸を運ばなかった。そんな中、\n番頭が、父の代わりに家業の差配を\n引き受け始めている。","pages_en":["The father lay unconscious,\nquietly, upon his bedding.\nBeside him, the mother took his hand\nand held it, silent.","At the forty-ninth day meal,\nthe household sat with chopsticks unmoved.\nMeanwhile, the head clerk\nhad begun to take charge of the trade","in the father's place."],"text_en":"The father lay unconscious,\nquietly, upon his bedding.\nBeside him, the mother took his hand\nand held it, silent.\nAt the forty-ninth day meal,\nthe household sat with chopsticks unmoved.\nMeanwhile, the head clerk\nhad begun to take charge of the trade\nin the father's place."},{"no":3,"img":"assets/images/chapter_11/IMG-091.webp","pages":["痩せた背に、家業の重みが\nにわかにのしかかったのである。\nその夜、屋敷の南面の書生の部屋では、\n書生がひとり、和紙を膝の上に広げていた。"],"text":"痩せた背に、家業の重みが\nにわかにのしかかったのである。\nその夜、屋敷の南面の書生の部屋では、\n書生がひとり、和紙を膝の上に広げていた。","pages_en":["Upon his thin back, the weight of the house\nsuddenly bore down.\nThat night, in the student's south room,\nhe sat alone,","a sheet of paper spread\nupon his knees."],"text_en":"Upon his thin back, the weight of the house\nsuddenly bore down.\nThat night, in the student's south room,\nhe sat alone,\na sheet of paper spread\nupon his knees."},{"no":4,"img":"assets/images/chapter_22/IMG-149.webp","pages":["そこへ、襖が音もなく開き、\n叔母が裾を引いて入ってきた。\n「お前様の、まことの素性を、\n私は知っておるよ」","叔母の声は低く、澄み切っていた。\n「お前様は、呪術の符牒を探しに、\nこの家に潜り込んだ者じゃろう」\n書生は応えを返さなかった。"],"text":"そこへ、襖が音もなく開き、\n叔母が裾を引いて入ってきた。\n「お前様の、まことの素性を、\n私は知っておるよ」\n叔母の声は低く、澄み切っていた。\n「お前様は、呪術の符牒を探しに、\nこの家に潜り込んだ者じゃろう」\n書生は応えを返さなかった。","pages_en":["Without a sound the door slid open,\nand the aunt entered,\ntrailing her hem.\n\"Your true nature ─","I know it.\"\nHer voice was low, crystalline.\n\"You slipped into this house\nseeking the ciphers of the spellcraft.\"","The student gave no reply."],"text_en":"Without a sound the door slid open,\nand the aunt entered,\ntrailing her hem.\n\"Your true nature ─\nI know it.\"\nHer voice was low, crystalline.\n\"You slipped into this house\nseeking the ciphers of the spellcraft.\"\nThe student gave no reply."},{"no":5,"img":"assets/images/chapter_09/IMG-080.webp","pages":["書生の咽の奥から、\n絞り出すような呼吸の音だけが洩れる。"],"text":"書生の咽の奥から、\n絞り出すような呼吸の音だけが洩れる。","pages_en":["Only the sound of forced breath\nescaped from his throat."],"text_en":"Only the sound of forced breath\nescaped from his throat."},{"no":6,"img":"assets/images/chapter_22/IMG-150.webp","pages":["「言うな。\n私はお前様を責めはせぬ。\nだが、もうこの家には居られぬよ」"],"text":"「言うな。\n私はお前様を責めはせぬ。\nだが、もうこの家には居られぬよ」","pages_en":["\"Say nothing.\nI shall not accuse you.\nBut you can no longer remain here.\""],"text_en":"\"Say nothing.\nI shall not accuse you.\nBut you can no longer remain here.\""},{"no":7,"img":"assets/images/chapter_22/IMG-151.webp","pages":["「呪術の真相は、\nお前様の家にも、必ず祟る」\n叔母はそう告げ、襖を音もなく閉ざして\n廊下を去ってゆく。"],"text":"「呪術の真相は、\nお前様の家にも、必ず祟る」\n叔母はそう告げ、襖を音もなく閉ざして\n廊下を去ってゆく。","pages_en":["\"The true nature of the spellcraft\nwill fall as curse\nupon your own house as well.\"\nThe aunt closed the door and vanished."],"text_en":"\"The true nature of the spellcraft\nwill fall as curse\nupon your own house as well.\"\nThe aunt closed the door and vanished."},{"no":8,"img":"assets/images/chapter_22/IMG-152.webp","pages":["叔母の去った後、書生は廊下を渡って、\n座牢の障子の前でふいに立ち止まる。\n障子越しに、書生の声が震えていた。","「お前様の家の呪術は、\n外を焦がるる娘の、その心そのものを、\n贄として食らう呪術にござります」","「『外を望む娘』が一代に一人生まれ、\nその娘の心が屋敷の繁栄を生むので\nござりまする。されど娘の心が満たされる時\n娘は、家の中で死なねばならぬのです」"],"text":"叔母の去った後、書生は廊下を渡って、\n座牢の障子の前でふいに立ち止まる。\n障子越しに、書生の声が震えていた。\n「お前様の家の呪術は、\n外を焦がるる娘の、その心そのものを、\n贄として食らう呪術にござります」\n「『外を望む娘』が一代に一人生まれ、\nその娘の心が屋敷の繁栄を生むので\nござりまする。されど娘の心が満たされる時\n娘は、家の中で死なねばならぬのです」","pages_en":["After she had gone,\nthe student crossed the hall\nand paused before the Cell's door.\nHis voice, through the paper, trembled.","\"The spellcraft of this house\nfeeds upon the very heart\nof a girl who yearns for the outside.\nIt takes that heart as offering.\"","\"Once in each generation is born\n'a girl who longs for outside,'\nand her longing feeds the manor's fortune.\nYet when her heart is at last fulfilled ─","she must die\nwithin this house.\""],"text_en":"After she had gone,\nthe student crossed the hall\nand paused before the Cell's door.\nHis voice, through the paper, trembled.\n\"The spellcraft of this house\nfeeds upon the very heart\nof a girl who yearns for the outside.\nIt takes that heart as offering.\"\n\"Once in each generation is born\n'a girl who longs for outside,'\nand her longing feeds the manor's fortune.\nYet when her heart is at last fulfilled ─\nshe must die\nwithin this house.\""},{"no":9,"img":"assets/images/chapter_22/IMG-153.webp","pages":["同じ刻、屋敷の別の座敷では、\n母と叔母が向かい合っていた。\n母の頬には、すでに涙の跡が\n幾筋にも伸びている。"],"text":"同じ刻、屋敷の別の座敷では、\n母と叔母が向かい合っていた。\n母の頬には、すでに涙の跡が\n幾筋にも伸びている。","pages_en":["At that same hour, in another chamber,\nthe mother and the aunt sat face to face.\nOn the mother's cheeks,\ntear-tracks already trailed."],"text_en":"At that same hour, in another chamber,\nthe mother and the aunt sat face to face.\nOn the mother's cheeks,\ntear-tracks already trailed."},{"no":10,"img":"assets/images/chapter_22/IMG-154.webp","pages":["母は絞り出すような声をあげた。\n「あの子のまことの母は──たま」\n「御祖父様が、手を出された\n下女にござります」"],"text":"母は絞り出すような声をあげた。\n「あの子のまことの母は──たま」\n「御祖父様が、手を出された\n下女にござります」","pages_en":["The mother pressed out a voice:\n\"That child's true mother\nwas Tama ─ a maidservant\nGrandfather laid a hand upon.\""],"text_en":"The mother pressed out a voice:\n\"That child's true mother\nwas Tama ─ a maidservant\nGrandfather laid a hand upon.\""},{"no":11,"img":"assets/images/chapter_22/IMG-155.webp","pages":["父の寝所では、人事不省の父の手が、\n寝間着の襟の下で、わずかに\n親指を解いていた。それは誰の目にも\n映らぬほどの、ささやかな動きであった。"],"text":"父の寝所では、人事不省の父の手が、\n寝間着の襟の下で、わずかに\n親指を解いていた。それは誰の目にも\n映らぬほどの、ささやかな動きであった。","pages_en":["In the father's chamber,\nthe hand of the unconscious father,\nbeneath the collar of his sleeping robe,\nslightly unfolded a thumb ─","a motion so small\nno eye could catch it."],"text_en":"In the father's chamber,\nthe hand of the unconscious father,\nbeneath the collar of his sleeping robe,\nslightly unfolded a thumb ─\na motion so small\nno eye could catch it."},{"no":12,"img":"assets/images/chapter_22/IMG-156.webp","pages":["娘の手の中では、螺鈿の貝殻が震えていた。\n震えは、異質な気配に対する恐れではない。\n娘の手の奥底、説明のつかない場所から、\n確かに昇ってきていたのであった。"],"text":"娘の手の中では、螺鈿の貝殻が震えていた。\n震えは、異質な気配に対する恐れではない。\n娘の手の奥底、説明のつかない場所から、\n確かに昇ってきていたのであった。","pages_en":["Within the girl's hand,\nthe mother-of-pearl shell trembled.\nIt was not the fear of the strange air,\nbut something rising","from the very depths\nof her hand ─\nfrom a place she could not name."],"text_en":"Within the girl's hand,\nthe mother-of-pearl shell trembled.\nIt was not the fear of the strange air,\nbut something rising\nfrom the very depths\nof her hand ─\nfrom a place she could not name."}]},{"title":"第二十四章 ─ 業火と門越え","folder":"chapter_23","taps":[{"no":1,"img":"assets/images/chapter_23/IMG-157.webp","pages":["屋敷の祭壇の前に、兄が立っている。\n書生や母の声を、襖越しに、\n兄はずっと聞いていた。\nやがて――兄の唇が、ふいに低く動く。","「俺の母も、父様の妾。下女のたまも、妾。\nということは……、俺もまた、\nこの家の贄の子か」"],"text":"屋敷の祭壇の前に、兄が立っている。\n書生や母の声を、襖越しに、\n兄はずっと聞いていた。\nやがて――兄の唇が、ふいに低く動く。\n「俺の母も、父様の妾。下女のたまも、妾。\nということは……、俺もまた、\nこの家の贄の子か」","pages_en":["Before the altar stood the elder brother.\nThe voices of the student and mother,\nhe had listened to them all\nthrough the doors.","At last, his lips moved low.\n\"My mother was Father's concubine.\nSo was the maid Tama.\nWhich means… I too,","am one of this manor's offering children.\""],"text_en":"Before the altar stood the elder brother.\nThe voices of the student and mother,\nhe had listened to them all\nthrough the doors.\nAt last, his lips moved low.\n\"My mother was Father's concubine.\nSo was the maid Tama.\nWhich means… I too,\nam one of this manor's offering children.\""},{"no":2,"img":"assets/images/chapter_23/IMG-158.webp","pages":["兄の手が、わなわなと震えた。\n祭壇の蝋燭が、その震えに揺られて、\nことりと倒れる。"],"text":"兄の手が、わなわなと震えた。\n祭壇の蝋燭が、その震えに揺られて、\nことりと倒れる。","pages_en":["His hands shook, and shook again.\nThe altar's candle, jarred by the tremor,\ntoppled with a soft ring."],"text_en":"His hands shook, and shook again.\nThe altar's candle, jarred by the tremor,\ntoppled with a soft ring."},{"no":3,"img":"assets/images/chapter_23/IMG-159.webp","pages":["兄が幾夜にも渡って方々に運んできた油は、\nその瞬間、燃える運命を背負った。\n炎は白き紙垂を舐め、襖を伝い、\n廊下を一気に走ってゆく。","屋敷の中には、見る間に煙が満ちていった。\n座牢の格子もまた、炎に焼かれ、\n軋み始めている。そこへ、書生が駆けつけ、\n座牢の錠を一息に断ち切った。"],"text":"兄が幾夜にも渡って方々に運んできた油は、\nその瞬間、燃える運命を背負った。\n炎は白き紙垂を舐め、襖を伝い、\n廊下を一気に走ってゆく。\n屋敷の中には、見る間に煙が満ちていった。\n座牢の格子もまた、炎に焼かれ、\n軋み始めている。そこへ、書生が駆けつけ、\n座牢の錠を一息に断ち切った。","pages_en":["The oil the brother had carried\nnight after night, place to place,\nin that instant\ntook up its destiny to burn.","Flame licked the white paper streamers,\nran along the sliding doors,\nand tore through the corridor at speed.\nSmoke filled the manor in an instant.","The lattice of the Cell itself\nbegan to burn and creak.\nThe student rushed to the Cell\nand broke the lock in a single stroke."],"text_en":"The oil the brother had carried\nnight after night, place to place,\nin that instant\ntook up its destiny to burn.\nFlame licked the white paper streamers,\nran along the sliding doors,\nand tore through the corridor at speed.\nSmoke filled the manor in an instant.\nThe lattice of the Cell itself\nbegan to burn and creak.\nThe student rushed to the Cell\nand broke the lock in a single stroke."},{"no":4,"img":"assets/images/chapter_23/IMG-160.webp","pages":["番頭は、火の手の中から、震える弟と妹を\n抱え上げ、外へと走ってゆく。家業ではなく\n命を背負った、最後の姿であった。\n書生は娘の手を、強く引いた。"],"text":"番頭は、火の手の中から、震える弟と妹を\n抱え上げ、外へと走ってゆく。家業ではなく\n命を背負った、最後の姿であった。\n書生は娘の手を、強く引いた。","pages_en":["The head clerk lifted the trembling siblings\nfrom the smoke and rushed outside.\nNot the trade, but their lives,\nhe bore on his back in the end.","The student pulled the girl's hand\nwith all his strength."],"text_en":"The head clerk lifted the trembling siblings\nfrom the smoke and rushed outside.\nNot the trade, but their lives,\nhe bore on his back in the end.\nThe student pulled the girl's hand\nwith all his strength."},{"no":5,"img":"assets/images/chapter_23/IMG-161.webp","pages":["廊下を駆け抜ける途中、\n人事不省の父の寝所が、娘の目に入った。\n父は動かぬまま、炎の中にあった。\n父の唇は、半ば開いている。"],"text":"廊下を駆け抜ける途中、\n人事不省の父の寝所が、娘の目に入った。\n父は動かぬまま、炎の中にあった。\n父の唇は、半ば開いている。","pages_en":["As they fled through the hall,\nthe father's chamber came into sight.\nMotionless, he lay within the fire.\nHis lips, half open."],"text_en":"As they fled through the hall,\nthe father's chamber came into sight.\nMotionless, he lay within the fire.\nHis lips, half open."},{"no":6,"img":"assets/images/chapter_23/IMG-161.webp","pages":["それが祖父の名であったか、\n母の名であったか、たまの名であったか、\n娘には知る術が、ない。\n父はそのままの姿で、炎に呑まれていった。","そして母の姿は、廊下のどこにも\n見当たらなかった。\nやがて娘と書生は玄関を抜け、\n屋敷の門前へと辿り着く。"],"text":"それが祖父の名であったか、\n母の名であったか、たまの名であったか、\n娘には知る術が、ない。\n父はそのままの姿で、炎に呑まれていった。\nそして母の姿は、廊下のどこにも\n見当たらなかった。\nやがて娘と書生は玄関を抜け、\n屋敷の門前へと辿り着く。","pages_en":["Whether it was Grandfather's name,\nor Mother's, or Tama's ─\nthe girl had no way to know.\nThe father was swallowed by the flames","as he lay.\nAnd of the mother,\nthere was no trace anywhere\nin the corridors.","At length, the girl and the student\npassed through the entrance\nand reached the manor's gate."],"text_en":"Whether it was Grandfather's name,\nor Mother's, or Tama's ─\nthe girl had no way to know.\nThe father was swallowed by the flames\nas he lay.\nAnd of the mother,\nthere was no trace anywhere\nin the corridors.\nAt length, the girl and the student\npassed through the entrance\nand reached the manor's gate."},{"no":7,"img":"assets/images/chapter_23/IMG-162.webp","pages":["屋敷は、もう業火に深く包まれている。\n娘は両手の親指を、隠さなかった。\n両の親指を夜の空に向けて、まっすぐに\n差し出したのである。","娘は門の敷居を、ついに踏み越えた。\n火の粉が夜空に舞い、そして消えてゆく。\n娘の懐には桐の小箱がなお抱かれていた。","その中で、螺鈿の貝殻が、\n屋敷の炎とは別の\n淡い光を、確かに放っていたのであった。"],"text":"屋敷は、もう業火に深く包まれている。\n娘は両手の親指を、隠さなかった。\n両の親指を夜の空に向けて、まっすぐに\n差し出したのである。\n娘は門の敷居を、ついに踏み越えた。\n火の粉が夜空に舞い、そして消えてゆく。\n娘の懐には桐の小箱がなお抱かれていた。\nその中で、螺鈿の貝殻が、\n屋敷の炎とは別の\n淡い光を、確かに放っていたのであった。","pages_en":["The manor was already deep in hellfire.\nThe girl did not hide her thumbs.\nBoth thumbs she thrust straight\ntoward the night sky.","She crossed the threshold of the gate.\nSparks danced in the night and vanished.\nStill, in her bosom,\nthe paulownia box was cradled.","And within it,\nthe mother-of-pearl shell\ngave off a pale light of its own,\nunmixed with the flames of the house."],"text_en":"The manor was already deep in hellfire.\nThe girl did not hide her thumbs.\nBoth thumbs she thrust straight\ntoward the night sky.\nShe crossed the threshold of the gate.\nSparks danced in the night and vanished.\nStill, in her bosom,\nthe paulownia box was cradled.\nAnd within it,\nthe mother-of-pearl shell\ngave off a pale light of its own,\nunmixed with the flames of the house."}]},{"title":"終幕 ─ 円環","folder":"chapter_finale","taps":[{"no":1,"img":"assets/images/chapter_finale/IMG-163.webp","pages":["数月の後、ある街の片隅で、\n新聞紙が風にひらりと舞っていた。\n古き商家、業火に包まれて、\n家系の絶ゆ。火元、確かならず。","生存者、一名。\nその一名の行方を、知る者は誰もいない。\nそれから、さらに数年の後。"],"text":"数月の後、ある街の片隅で、\n新聞紙が風にひらりと舞っていた。\n古き商家、業火に包まれて、\n家系の絶ゆ。火元、確かならず。\n生存者、一名。\nその一名の行方を、知る者は誰もいない。\nそれから、さらに数年の後。","pages_en":["Some months later, in a corner of a town,\na sheet of newspaper danced in the wind.\n\"An old merchant house\nswallowed by hellfire, its line ended.\"","\"The origin of the flame remains unclear.\nSurvivor: one.\"\nWhere that one had gone\nno one knew. And then,","several more years passed."],"text_en":"Some months later, in a corner of a town,\na sheet of newspaper danced in the wind.\n\"An old merchant house\nswallowed by hellfire, its line ended.\"\n\"The origin of the flame remains unclear.\nSurvivor: one.\"\nWhere that one had gone\nno one knew. And then,\nseveral more years passed."},{"no":2,"img":"assets/images/chapter_finale/IMG-164.webp","pages":["街道のかたわら、白壁の屋敷の門前で、\nひとりの女が、ふと足を止めた。\n紫紺の羽織を肩に着た、女である。","屋敷の門には、籠目模様の格子戸が、\nしんと立てかけられていた。\nその奥の座敷の障子には、\n年若き娘の影が、ふっと映っている。","紫紺の女は、格子戸の隙間に\nそっと口を寄せる。\n「外を、御覧なされ」と。","「ここ以外の空の色は、青き、青き、\nまことに青きものにござります」\n女の口の端には、微かな笑みが\n浮かんでいる。"],"text":"街道のかたわら、白壁の屋敷の門前で、\nひとりの女が、ふと足を止めた。\n紫紺の羽織を肩に着た、女である。\n屋敷の門には、籠目模様の格子戸が、\nしんと立てかけられていた。\nその奥の座敷の障子には、\n年若き娘の影が、ふっと映っている。\n紫紺の女は、格子戸の隙間に\nそっと口を寄せる。\n「外を、御覧なされ」と。\n「ここ以外の空の色は、青き、青き、\nまことに青きものにござります」\n女の口の端には、微かな笑みが\n浮かんでいる。","pages_en":["Beside a country road,\nat the gate of a white-walled manor,\na woman paused her step.\nShe wore a deep-violet haori.","The manor gate held\na latticed door of kagome pattern,\nstanding still.\nBeyond it, on the paper of a chamber,","the shadow of a young girl\nquietly appeared.\nThe woman in violet\nleaned her lips to a crack of the lattice,","and whispered:\n\"Look outside.\"\n\"The color of the sky elsewhere\nis blue ─ blue,","a truer blue than you may know.\"\nA faint smile\nlingered at the corner of her lips."],"text_en":"Beside a country road,\nat the gate of a white-walled manor,\na woman paused her step.\nShe wore a deep-violet haori.\nThe manor gate held\na latticed door of kagome pattern,\nstanding still.\nBeyond it, on the paper of a chamber,\nthe shadow of a young girl\nquietly appeared.\nThe woman in violet\nleaned her lips to a crack of the lattice,\nand whispered:\n\"Look outside.\"\n\"The color of the sky elsewhere\nis blue ─ blue,\na truer blue than you may know.\"\nA faint smile\nlingered at the corner of her lips."},{"no":3,"img":"assets/images/chapter_finale/IMG-165.webp","pages":["螺鈿の貝殻が、女の懐で月光のように\n淡く光っていた……。"],"text":"螺鈿の貝殻が、女の懐で月光のように\n淡く光っていた……。","pages_en":["The mother-of-pearl shell\nglowed pale in the woman's bosom,\nlike moonlight…"],"text_en":"The mother-of-pearl shell\nglowed pale in the woman's bosom,\nlike moonlight…"}]}];
